/* Undercurrent case-study sandbox — scoped design tokens.
   This is a visual clone of the real Undercurrent design system (a separate
   React+MUI+Emotion repo), rebuilt from scratch for this one demo. These
   tokens intentionally mirror Undercurrent's real semantic token *names*
   (neutral bg/text/border/icon, plus highlight/success/warning/danger color
   groups) so this file stays easy to audit against the real system, but the
   values only cover what the 7 demo components actually use — this is not
   a general-purpose token system.

   Only imported by the sandbox's root component, so these rules never
   affect any other page. */

/* ─── Base typography ───────────────────────────────────────────────────
   The case-study article body (.article-body in ProjectLayout.astro) sets
   font-family: var(--font-plex-sans) on itself, which every element in the
   MDX content inherits by default — including this island, since it renders
   real DOM nodes inside that wrapper. Undercurrent's real components use
   Geist Sans, so it's set explicitly here rather than relying on whatever
   the surrounding page happens to inherit. Geist Mono (secondary/technical
   text) is set per-element where needed, same as the real design system. */
.uc-demo {
  font-family: var(--font-sans);
}

/* Every demo component reads its colors from --uc-demo-active-*, which
   changes instantly the moment data-uc-variant flips (CSS custom
   properties aren't themselves animatable) — this is what makes the actual
   painted color properties glide instead of snapping when the swatch
   switches. Scoped to [data-uc-variant]'s own descendants specifically
   (the inner bordered frame holding the 7 demo components), not the outer
   .uc-demo wrapper — the swatch row also lives under .uc-demo but already
   has its own motion/react-driven transition, and applying both here too
   would fight over the same background-color/color properties. */
[data-uc-variant] :where(*) {
  transition:
    background-color 200ms ease-out,
    border-color 200ms ease-out,
    color 200ms ease-out;
}

/* ─── Neutral tokens (dark is the default; .dark class matches this file's
   own scope the same way global.css's :root/.dark pair does) ───────────── */
.uc-demo {
  --uc-demo-neutral-bg-main: #262523;
  --uc-demo-neutral-bg-weak: #181716;
  --uc-demo-neutral-bg-strong: #ffffff;
  --uc-demo-neutral-text-main: #ffffff;
  --uc-demo-neutral-text-medium: #e6e5e4;
  --uc-demo-neutral-text-weak: #a7a49f;
  --uc-demo-neutral-text-strong: #181716;
  --uc-demo-neutral-border-weak: #43413d;
  --uc-demo-neutral-icon-weak: #a7a49f;

  /* ─── Color groups (raw values, before the active-variant redirection) ── */
  --uc-demo-highlight-bg-main: #1c42a8;
  --uc-demo-highlight-bg-strong: #bad2fd;
  --uc-demo-highlight-border-weak: #2159d4;
  --uc-demo-highlight-border-main: #bad2fd;
  --uc-demo-highlight-border-medium: #6097f9;
  --uc-demo-highlight-text-main: #bad2fd;
  --uc-demo-highlight-text-weak: #1c42a8;
  --uc-demo-highlight-icon-main: #bad2fd;

  --uc-demo-success-bg-main: #14532d;
  --uc-demo-success-bg-strong: #bbf7d0;
  --uc-demo-success-border-weak: #166534;
  --uc-demo-success-border-main: #86efac;
  --uc-demo-success-text-main: #86efac;
  --uc-demo-success-text-weak: #14532d;
  --uc-demo-success-icon-main: #86efac;

  --uc-demo-warning-bg-main: #713f12;
  --uc-demo-warning-bg-strong: #fde047;
  --uc-demo-warning-border-weak: #854d0e;
  --uc-demo-warning-border-main: #fde047;
  --uc-demo-warning-text-main: #fde047;
  --uc-demo-warning-text-weak: #713f12;
  --uc-demo-warning-icon-main: #fde047;

  --uc-demo-danger-bg-main: #7f1d1d;
  --uc-demo-danger-bg-strong: #fecaca;
  --uc-demo-danger-border-weak: #991b1b;
  --uc-demo-danger-border-main: #fca5a5;
  --uc-demo-danger-text-main: #f87171;
  --uc-demo-danger-text-weak: #7f1d1d;
  --uc-demo-danger-icon-main: #f87171;

  /* ─── Swatch chip colors (the 4 color-toggle buttons above the demo
     frame) — a distinct, fixed color pairing per swatch, separate from the
     -bg-main/-text-main tokens above since those are tuned for the demo
     components' own surfaces, not this chip's specific look. */
  --uc-demo-swatch-highlight-text: #eef4ff;
  --uc-demo-swatch-highlight-bg: #1c42a8;
  --uc-demo-swatch-success-text: #dcfce7;
  --uc-demo-swatch-success-bg: #14532d;
  --uc-demo-swatch-warning-text: #fef9c3;
  --uc-demo-swatch-warning-bg: #713f12;
  --uc-demo-swatch-danger-text: #fee2e2;
  --uc-demo-swatch-danger-bg: #7f1d1d;
}

.dark .uc-demo,
.uc-demo.dark {
  /* Dark values are identical to the base block above — this site defaults
     its color-scheme detection through a `.dark` class on <html>, and the
     sandbox's dark tokens ARE the defaults. This rule exists so light mode
     (below) has something concrete to override, and so the dark values are
     explicit rather than "whatever happens if nothing overrides them." */
  --uc-demo-neutral-bg-main: #262523;
  --uc-demo-neutral-bg-weak: #181716;
  --uc-demo-neutral-bg-strong: #ffffff;
  --uc-demo-neutral-text-main: #ffffff;
  --uc-demo-neutral-text-medium: #e6e5e4;
  --uc-demo-neutral-text-weak: #a7a49f;
  --uc-demo-neutral-text-strong: #181716;
  --uc-demo-neutral-border-weak: #43413d;
  --uc-demo-neutral-icon-weak: #a7a49f;
}

/* ─── Light mode overrides ──────────────────────────────────────────────── */
/* :not(.dark) on .uc-demo itself (not just on :root) matters here: without
   it, this descendant selector's specificity (0,3,0) beats .uc-demo.dark's
   (0,2,0) and silently overrides a ThemeRevealSandbox half that explicitly
   opted into .dark, any time the PAGE itself happens to be in light mode —
   :root:not(.dark) only rules out :root carrying .dark, it says nothing
   about a nested element that carries its own .dark class. */
:root:not(.dark) .uc-demo:not(.dark),
.uc-demo.light {
  --uc-demo-neutral-bg-main: #ffffff;
  --uc-demo-neutral-bg-weak: #f6f5f4;
  --uc-demo-neutral-bg-strong: #191715;
  --uc-demo-neutral-text-main: #191715;
  --uc-demo-neutral-text-medium: #46413a;
  --uc-demo-neutral-text-weak: #5a534a;
  --uc-demo-neutral-text-strong: #ffffff;
  --uc-demo-neutral-border-weak: #e8e5e2;
  --uc-demo-neutral-icon-weak: #5a534a;

  --uc-demo-highlight-bg-main: #eef4ff;
  --uc-demo-highlight-bg-strong: #3d7bf5;
  --uc-demo-highlight-border-weak: #dce9fe;
  --uc-demo-highlight-border-main: #3d7bf5;
  --uc-demo-highlight-border-medium: #90b6fc;
  --uc-demo-highlight-text-main: #3d7bf5;
  --uc-demo-highlight-text-weak: #eef4ff;
  --uc-demo-highlight-icon-main: #3d7bf5;

  --uc-demo-success-bg-main: #f0fdf4;
  --uc-demo-success-bg-strong: #15803d;
  --uc-demo-success-border-weak: #dcfce7;
  --uc-demo-success-border-main: #15803d;
  --uc-demo-success-text-main: #15803d;
  --uc-demo-success-text-weak: #f0fdf4;
  --uc-demo-success-icon-main: #15803d;

  --uc-demo-warning-bg-main: #fef9c3;
  --uc-demo-warning-bg-strong: #facc15;
  --uc-demo-warning-border-weak: #fef08a;
  --uc-demo-warning-border-main: #a16207;
  --uc-demo-warning-text-main: #a16207;
  --uc-demo-warning-text-weak: #fef9c3;
  --uc-demo-warning-icon-main: #a16207;

  --uc-demo-danger-bg-main: #fef2f2;
  --uc-demo-danger-bg-strong: #dc2626;
  --uc-demo-danger-border-weak: #fee2e2;
  --uc-demo-danger-border-main: #b91c1c;
  --uc-demo-danger-text-main: #b91c1c;
  --uc-demo-danger-text-weak: #fef2f2;
  --uc-demo-danger-icon-main: #b91c1c;

  --uc-demo-swatch-highlight-text: #2159d4;
  --uc-demo-swatch-highlight-bg: #dce9fe;
  --uc-demo-swatch-success-text: #166534;
  --uc-demo-swatch-success-bg: #dcfce7;
  --uc-demo-swatch-warning-text: #854d0e;
  --uc-demo-swatch-warning-bg: #fef08a;
  --uc-demo-swatch-danger-text: #b91c1c;
  --uc-demo-swatch-danger-bg: #fee2e2;
}

/* ─── Active-variant redirection ────────────────────────────────────────
   Components only ever read --uc-demo-active-*. Switching the color swatch
   is just flipping this one data attribute on the sandbox root — the
   cascade does the rest, no per-component JS lookup needed. */
.uc-demo[data-uc-variant="highlight"] {
  --uc-demo-active-bg-main: var(--uc-demo-highlight-bg-main);
  --uc-demo-active-bg-strong: var(--uc-demo-highlight-bg-strong);
  --uc-demo-active-border-weak: var(--uc-demo-highlight-border-weak);
  --uc-demo-active-border-main: var(--uc-demo-highlight-border-main);
  --uc-demo-active-border-medium: var(--uc-demo-highlight-border-medium);
  --uc-demo-active-text-main: var(--uc-demo-highlight-text-main);
  --uc-demo-active-text-weak: var(--uc-demo-highlight-text-weak);
  --uc-demo-active-icon-main: var(--uc-demo-highlight-icon-main);
}

.uc-demo[data-uc-variant="success"] {
  --uc-demo-active-bg-main: var(--uc-demo-success-bg-main);
  --uc-demo-active-bg-strong: var(--uc-demo-success-bg-strong);
  --uc-demo-active-border-weak: var(--uc-demo-success-border-weak);
  --uc-demo-active-border-main: var(--uc-demo-success-border-main);
  --uc-demo-active-border-medium: var(--uc-demo-success-border-main);
  --uc-demo-active-text-main: var(--uc-demo-success-text-main);
  --uc-demo-active-text-weak: var(--uc-demo-success-text-weak);
  --uc-demo-active-icon-main: var(--uc-demo-success-icon-main);
}

.uc-demo[data-uc-variant="warning"] {
  --uc-demo-active-bg-main: var(--uc-demo-warning-bg-main);
  --uc-demo-active-bg-strong: var(--uc-demo-warning-bg-strong);
  --uc-demo-active-border-weak: var(--uc-demo-warning-border-weak);
  --uc-demo-active-border-main: var(--uc-demo-warning-border-main);
  --uc-demo-active-border-medium: var(--uc-demo-warning-border-main);
  --uc-demo-active-text-main: var(--uc-demo-warning-text-main);
  --uc-demo-active-text-weak: var(--uc-demo-warning-text-weak);
  --uc-demo-active-icon-main: var(--uc-demo-warning-icon-main);
}

.uc-demo[data-uc-variant="danger"] {
  --uc-demo-active-bg-main: var(--uc-demo-danger-bg-main);
  --uc-demo-active-bg-strong: var(--uc-demo-danger-bg-strong);
  --uc-demo-active-border-weak: var(--uc-demo-danger-border-weak);
  --uc-demo-active-border-main: var(--uc-demo-danger-border-main);
  --uc-demo-active-border-medium: var(--uc-demo-danger-border-main);
  --uc-demo-active-text-main: var(--uc-demo-danger-text-main);
  --uc-demo-active-text-weak: var(--uc-demo-danger-text-weak);
  --uc-demo-active-icon-main: var(--uc-demo-danger-icon-main);
}

/* ─── Shared sizing scale (matches Undercurrent's theme.spacing/size/radius) ─ */
.uc-demo {
  --uc-demo-space-50: 4px;
  --uc-demo-space-100: 8px;
  --uc-demo-space-150: 12px;
  --uc-demo-space-200: 16px;
  --uc-demo-space-300: 24px;

  --uc-demo-radius-xs: 6px;
  --uc-demo-radius-sm: 8px;
  --uc-demo-radius-md: 12px;
  --uc-demo-radius-full: 360px;

  --uc-demo-size-xs: 16px;
  --uc-demo-size-sm: 24px;
  --uc-demo-size-md: 32px;
  --uc-demo-size-lg: 40px;
}

/* ─── Theme reveal slider tokens (ThemeRevealSandbox + its bespoke
   components — UcErrorCard, UcFieldRow, UcRetryBanner, UcTimeline). This
   island has no working color-variant switcher, so its interactive chrome
   (the drag handle) uses the case study's own brand color (the same
   iconColor/iconColorDark pair from undercurrent.mdx's frontmatter, #0B7FA8
   light / #2DC7FF dark) rather than --uc-demo-active-*, which only ever
   resolves to a hardcoded "danger" redirection here. */
.uc-demo {
  /* Timeline's connecting vertical line and the "neutral" status variant
     (an event that isn't a success, e.g. "Server has been stopped") both
     read as a dimmer, unaccented gray — distinct from the danger-red used
     by the retry banner above them. */
  --uc-demo-timeline-connector: var(--uc-demo-neutral-border-weak);
  --uc-demo-timeline-neutral-icon: var(--uc-demo-neutral-text-weak);
  --uc-demo-timeline-success-icon: var(--uc-demo-success-icon-main);

  /* Compact pill for "2 secs"-style duration tags — smaller than UcChip's
     fixed --uc-demo-size-md height, so this island uses bespoke sizing
     rather than stretching UcChip's own token past what it was tuned for. */
  --uc-demo-duration-tag-height: 20px;
  --uc-demo-duration-tag-padding-x: 6px;

  /* Drag handle: a single fixed neutral-violet tone, the same in both
     light and dark (not the brand color pair used elsewhere) — chosen
     directly, not theme-conditional. */
  --uc-demo-handle-color: oklch(62.2% 0.0224 286deg);
}

content.text:
Confirmed — every `strokeDasharray` usage in the current-gen "Graphs" module family is only the `CartesianGrid` background grid (`5 5` dashed grid lines), not a hover reference line. There is no `ReferenceLine`, `activeDot`, cursor customization, or any dashed-vertical-line-plus-dot hover indicator anywhere in this codebase. The tooltip is purely the floating `GraphTimeTooltip` box rendered via recharts' default `Tooltip` positioning.

Here is the full report.

## Branch/repo confirmation

Repo: `/Users/trounceabout/Documents/Repos/Work/wallaby`, branch `feature/epic-server-monitoring-dashboard` (already checked out, up to date with origin).

---

## 1. `src/components/Graphs/GraphTimeTooltip/GraphTimeTooltip.tsx`

```tsx
import dayjs from 'dayjs';
import { type TooltipProps } from 'recharts';

import Typography from '@liquidweb-dev/undercurrent/Typography';
import TooltipStack from 'components/Graphs/TooltipStack';
import {
	type Duration,
	tooltipDateFormat,
} from 'components/Graphs/graphMeasurements';

export interface GraphTimeTooltipProps extends TooltipProps<number, string> {
	duration: Duration;
}

/**
 * Recharts tooltip content that renders the hovered point's timestamp,
 * formatted per the given duration. `active`/`payload` are injected by recharts;
 * `duration` is supplied by the consuming chart.
 */
const GraphTimeTooltip = ({
	active,
	payload,
	duration,
}: GraphTimeTooltipProps) => {
	if (!active || !payload?.length) return null;
	const time = payload[0]?.payload?.time as number | undefined;
	if (time == null) return null;
	return (
		<TooltipStack>
			<Typography variant="label-md">
				{dayjs.unix(time).format(tooltipDateFormat(duration))}
			</Typography>
		</TooltipStack>
	);
};

export default GraphTimeTooltip;
```

**Behavior:** This is the `content` renderer passed to recharts' `<Tooltip>`. It receives `active`/`payload` from recharts automatically and a custom `duration` prop from the consuming chart. It renders nothing when inactive or empty. When active, it pulls `time` (a unix timestamp) off the first payload entry's underlying data point and formats it via `dayjs.unix(time).format(...)`, using `tooltipDateFormat(duration)` — `'MMM D, YYYY'` for `'2week'` duration, `'h:mm a'` otherwise. It wraps the label in `TooltipStack`, a styled `Stack`. **This is the entire tooltip — a floating box positioned by recharts' default tooltip positioning logic (no custom position/coordinate prop, no cursor customization, no reference line).**

## 2. `src/components/Graphs/TooltipStack/TooltipStack.jsx`

```jsx
// @ts-check

import React from 'react';
import Stack from '@liquidweb-dev/undercurrent/Stack';
import combineSx from '@liquidweb-dev/undercurrent/utility/combineSx';

/** @param {import('@liquidweb-dev/undercurrent/Stack').StackProps} props */
const TooltipStack = ({ sx, ...rest }) => {
	return (
		<Stack
			sx={combineSx(
				{
					backgroundColor: (theme) => theme.vars.palette.uc.bg.main,
					borderRadius: (theme) => theme.borderRadius.roundedXS,
					boxShadow: (theme) => theme.shadows[1],
					padding: (theme) => `${theme.spacing(50)} ${theme.spacing(100)}`,
					gap: 50,
				},
				sx,
			)}
			{...rest}
		/>
	);
};

export default TooltipStack;
```

**Behavior:** Pure styling wrapper around Undercurrent's `Stack`. Background = theme `uc.bg.main`, border-radius `roundedXS`, `boxShadow[1]` (a drop shadow), padding `spacing(50) spacing(100)` (vertical/horizontal), and internal `gap: 50` between stacked children. This is the visual "pill/card" box behind the tooltip content. It accepts any `Stack` props and merges `sx`.

## 3. `src/components/Graphs/StatHighlight/StatHighlight.tsx`

```tsx
import Box, { type BoxProps } from '@liquidweb-dev/undercurrent/Box';
import Typography from '@liquidweb-dev/undercurrent/Typography';
import TrendingUpIcon from '@liquidweb-dev/undercurrent/icons/lucide/TrendingUp';
import TrendingDownIcon from '@liquidweb-dev/undercurrent/icons/lucide/TrendingDown';
import combineSx from '@liquidweb-dev/undercurrent/utility/combineSx';

export interface StatHighlightProps extends BoxProps {
	/** Monospace label shown above the value, e.g. "1 min". Omit when the card header serves as the label. */
	label?: string;
	/**
	 * Full formatted value string including any short suffix, e.g. "64%", "75%", "3.8".
	 * Do NOT use unit= for %; unit= is for longer secondary values like "14.2/16 GB".
	 */
	value: string;
	/** Optional secondary value shown in the extras column, e.g. "14.2/16 GB". */
	unit?: string;
	/** Optional % change. Positive = up, negative = down. */
	changePercent?: number;
	/**
	 * Optional custom change label rendered instead of "±N%", e.g. "+1.5 GB/day".
	 * When provided, changePercent is not required — use changeDirection to control the icon.
	 */
	changeLabel?: string;
	/**
	 * Explicit icon direction when changeLabel is used without changePercent.
	 * Defaults to 'up' when changePercent >= 0.
	 */
	changeDirection?: 'up' | 'down';
	/**
	 * Color applied to the percent change icon and text. Defaults to text.weak.
	 * Pass a resolved CSS color for semantic meaning, e.g. vars.palette.uc.success.text.main.
	 */
	changeColor?: string;
	/** Optional 12×12 rounded-square color key shown in the label row (Load Average series). */
	iconColor?: string;
	/**
	 * Override color for the large value. Defaults to text.main.
	 * Pass a resolved CSS color, e.g. vars.palette.uc.danger.text.main for critical states.
	 */
	valueColor?: string;
}

/**
 * Stat highlight matching the Figma "Highlight" component spec.
 * Layout: label row → score row (large value + extras column).
 */
const StatHighlight = ({
	label,
	value,
	unit,
	changePercent,
	changeLabel,
	changeDirection,
	changeColor,
	iconColor,
	valueColor,
	sx,
	...rest
}: StatHighlightProps) => {
	const hasChange =
		(changePercent !== undefined && changePercent !== null) ||
		Boolean(changeLabel);
	// changeDirection wins; fall back to sign of changePercent; default to up when neither is set
	const isPositive =
		changeDirection === 'up' ||
		(changeDirection === undefined &&
			(changePercent !== undefined ? changePercent >= 0 : true));
	const hasExtras = Boolean(unit) || hasChange;

	return (
		<Box
			sx={combineSx({ display: 'flex', flexDirection: 'column', gap: 100 }, sx)}
			{...rest}
		>
			{/* Label row — only rendered when label or iconColor is provided */}
			{(label || iconColor) && (
				<Box sx={{ display: 'flex', alignItems: 'center', gap: 100 }}>
					{iconColor && (
						<Box
							sx={({ size, borderRadius }) => ({
								width: size.xXS,
								height: size.xXS,
								borderRadius: borderRadius.roundedSm,
								backgroundColor: iconColor,
								flexShrink: 0,
							})}
						/>
					)}
					<Typography
						fontType="monospace"
						variant="label-md"
						sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
					>
						{label}
					</Typography>
				</Box>
			)}

			{/* Score row */}
			<Box
				sx={{
					display: 'flex',
					alignItems: 'flex-end',
					gap: 100,
					width: '100%',
				}}
			>
				{/* Large value */}
				{/* TODO: hardcoded scale pending a typographic-scale decision; replace with a UC variant before release. */}
				<Typography
					sx={({ vars }) => ({
						fontSize: '40px',
						lineHeight: '38px',
						letterSpacing: '-0.64px',
						color: valueColor ?? vars.palette.uc.text.main,
						whiteSpace: 'nowrap',
					})}
				>
					{value}
				</Typography>

				{/* Extras column — unit + % change stacked */}
				{hasExtras && (
					<Box
						sx={{
							display: 'flex',
							flexDirection: 'column',
							alignItems: 'flex-start',
							justifyContent: 'flex-end',
							gap: 50,
						}}
					>
						{unit && (
							<Typography
								fontType="monospace"
								variant="label-md"
								sx={({ vars }) => ({
									color: vars.palette.uc.text.weak,
									whiteSpace: 'nowrap',
								})}
							>
								{unit}
							</Typography>
						)}

						{hasChange && (
							<Box
								sx={({ vars }) => ({
									display: 'flex',
									alignItems: 'center',
									gap: 50,
									color: changeColor ?? vars.palette.uc.text.weak,
								})}
							>
								{isPositive ? (
									<TrendingUpIcon
										sx={({ size }) => ({ width: size.xS, height: size.xS })}
									/>
								) : (
									<TrendingDownIcon
										sx={({ size }) => ({ width: size.xS, height: size.xS })}
									/>
								)}
								<Typography fontType="monospace" variant="label-md">
									{changeLabel ??
										`${isPositive ? '+' : '-'}${Math.abs(changePercent ?? 0)}%`}
								</Typography>
							</Box>
						)}
					</Box>
				)}
			</Box>
		</Box>
	);
};

export default StatHighlight;
```

**Behavior:** Two-row layout — optional label row (monospace weak-color text + optional 12×12 `roundedSm` color swatch via `iconColor`), then a score row with a large 40px/38px-line-height/-0.64px-letter-spacing value, and an "extras" column stacked to the right containing an optional `unit` (monospace, weak color) and an optional change indicator (Trending Up/Down lucide icon + monospace text, colored via `changeColor`, default `text.weak`). Change text defaults to `±N%` from `changePercent`, or a custom `changeLabel` string (e.g., "+1.5 GB/day", "New"). Direction/icon chosen by `changeDirection` if given, else sign of `changePercent`, defaulting to "up".

## 4. `src/components/Graphs/GraphCard/GraphCard.tsx`

```tsx
import { type ReactNode } from 'react';

import Card, { type CardProps } from '@liquidweb-dev/undercurrent/Card';
import CardContent from '@liquidweb-dev/undercurrent/CardContent';
import CardHeader from '@liquidweb-dev/undercurrent/CardHeader';
import CardLayeredFooter from '@liquidweb-dev/undercurrent/CardLayeredFooter';
import IconButton from '@liquidweb-dev/undercurrent/IconButton';
import Tooltip from '@liquidweb-dev/undercurrent/Tooltip';
import InfoIcon from '@liquidweb-dev/undercurrent/icons/lucide/Info';
import combineSx from '@liquidweb-dev/undercurrent/utility/combineSx';

export interface GraphCardInfoTooltip {
	message: string;
	ariaLabel: string;
	arrow?: boolean;
}

export interface GraphCardProps extends CardProps {
	title: string;
	infoTooltip?: GraphCardInfoTooltip;
	/** Optional footer content rendered in a CardLayeredFooter below the body. */
	footer?: ReactNode;
	/** Background color for the footer — pass a theme color for urgency treatment. */
	footerBgcolor?: string;
}

/**
 * Shared card chrome for graph modules: a Card with a titled header (and an
 * optional info tooltip action) wrapping the graph content, plus an optional
 * footer. Extends CardProps so callers can pass through any MUI Card prop and
 * merge their own sx.
 */
const GraphCard = ({
	title,
	infoTooltip,
	footer,
	footerBgcolor,
	sx,
	children,
	...rest
}: GraphCardProps) => (
	<Card
		sx={combineSx(
			{ display: 'flex', flexDirection: 'column', overflow: 'hidden' },
			sx,
		)}
		{...rest}
	>
		<CardHeader
			title={title}
			action={
				infoTooltip ? (
					<Tooltip
						arrow={infoTooltip.arrow}
						variant="fancy"
						title=""
						message={infoTooltip.message}
					>
						<IconButton
							variant="barebones"
							size="small"
							aria-label={infoTooltip.ariaLabel}
						>
							<InfoIcon />
						</IconButton>
					</Tooltip>
				) : undefined
			}
		/>
		<CardContent
			sx={{
				display: 'flex',
				flexDirection: 'column',
				flexGrow: 1,
				overflow: 'hidden',
				p: 0,
			}}
		>
			{children}
		</CardContent>
		{footer && (
			<CardLayeredFooter bgcolor={footerBgcolor}>{footer}</CardLayeredFooter>
		)}
	</Card>
);

export default GraphCard;
```

**Behavior:** The shared card chrome for every graph module — `Card` (flex column, `overflow: hidden`) → `CardHeader` (title + optional info-icon button with a "fancy" tooltip) → `CardContent` (flex-grow, `overflow: hidden`, `p: 0`, holds `children`) → optional `CardLayeredFooter` (with `bgcolor` override, used e.g. for danger-red disk-full footer).

## 5. `src/components/Graphs/graphMeasurements.ts`

```ts
import type { Theme } from '@mui/material/styles';
import type { LWApiPublicAssetMeasurementsLookupParamsRawI } from '@liquidweb-dev/club-sauce/public/asset/measurements/index.raw';
import { type StatHighlightProps } from 'components/Graphs/StatHighlight';

/** Measurement lookup duration window (e.g. '12hour', 'day', '2week'). */
export type Duration = LWApiPublicAssetMeasurementsLookupParamsRawI['duration'];

/**
 * Result of a change computation: a rounded percent, `'new'` when the previous
 * period/point was a genuine zero and the current value is positive (a real
 * signal, not a percentage), or undefined when unknown or flat.
 */
export type ChangeResult = number | 'new' | undefined;

/** dayjs format string for tooltip timestamps — date for long windows, time otherwise. */
export const tooltipDateFormat = (duration: Duration) =>
	duration === '2week' ? 'MMM D, YYYY' : 'h:mm a';

/**
 * Maps each display duration to a doubled window so we can fetch the previous
 * period alongside the current one and compute period-over-period change.
 * TODO: the doubled values here (e.g. day -> 3day, month -> 3month) need review;
 * this comparison will ultimately move to the backend API.
 */
export const DOUBLED_DURATION: Partial<Record<Duration, Duration>> = {
	'6hour': '12hour',
	'12hour': 'day',
	day: '3day',
	'2week': 'month',
	month: '3month',
} as const;

/** Mean of `key` across data points that have a value; skips null/missing readings. */
export const avg = (data: Array<Record<string, number>>, key: string) => {
	const present = data.filter((p) => p[key] != null);
	if (!present.length) return 0;
	return present.reduce((sum, p) => sum + p[key], 0) / present.length;
};

/**
 * Point-to-previous-point percentage change for `key` at `index`.
 * Returns undefined for the first point or when either value is missing.
 * Returns 'new' when the previous point was a genuine zero and the current
 * point is positive, rather than hiding the spike as "unknown".
 */
export const computeChange = (
	data: Array<Record<string, number>>,
	key: string,
	index: number,
): ChangeResult => {
	if (index < 1) return undefined;
	const current = data[index][key];
	const previous = data[index - 1][key];
	if (current == null || previous == null) return undefined;
	if (previous === 0) return current > 0 ? 'new' : undefined;
	return Math.round(((current - previous) / previous) * 100);
};

/**
 * Period-over-period percentage change between a current and previous average.
 * See ChangeResult for the 'new'-baseline sentinel.
 */
export const periodChange = (
	currentAvg: number,
	prevAvg: number,
): ChangeResult => {
	if (prevAvg === 0) return currentAvg > 0 ? 'new' : undefined;
	return Math.round(((currentAvg - prevAvg) / prevAvg) * 100);
};

/** Danger for an increase (including 'new'), success for a decrease; undefined when change is flat or unknown. */
export const changeColorForIncrease = (
	changePercent: ChangeResult,
	theme: Theme,
) => {
	if (changePercent === undefined) return undefined;
	if (changePercent === 'new' || changePercent > 0)
		return theme.vars.palette.uc.danger.text.main;
	if (typeof changePercent === 'number' && changePercent < 0)
		return theme.vars.palette.uc.success.text.main;
	return undefined;
};

/** Maps a ChangeResult to the StatHighlight props that render it. */
export const changeResultToStatHighlightProps = (
	change: ChangeResult,
): Pick<
	StatHighlightProps,
	'changePercent' | 'changeLabel' | 'changeDirection'
> => {
	if (change === 'new') return { changeLabel: 'New', changeDirection: 'up' };
	if (change === undefined) return {};
	return { changePercent: change };
};
```

**Behavior:** Shared math/formatting utilities. `tooltipDateFormat` — the key detail: `'2week'` duration → `'MMM D, YYYY'` (e.g. "May 9, 2026"); every other duration → `'h:mm a'` (e.g. "2:30 pm"). `DOUBLED_DURATION` maps a display window to a "fetch double, split at midpoint" window used by all the charts to compute period-over-period change. `avg`, `computeChange` (point-to-previous-point %), `periodChange` (avg-vs-avg %), `changeColorForIncrease` (danger red if increase/new, success green if decrease), and `changeResultToStatHighlightProps` (adapts a `ChangeResult` into `StatHighlight` props, turning `'new'` into a `changeLabel: 'New'`).

