## 7. `src/components/Graphs/Bars/Bars.jsx`

```jsx
// @ts-check
import React from 'react';

/**
 * @typedef BarPathProps
 * @property {boolean} isTop
 * @property {number} x
 * @property {number} y
 * @property {number} width
 * @property {number} height
 */

/**
 * @param {BarPathProps} props
 */
const getBarPath = ({ isTop, x, y, width, height }) => {
	const radius = 4;
	const bottomExtension = isTop ? 6 : 0;
	return `M${x},${y + height + bottomExtension}
			L${x},${y + radius}
			Q${x},${y} ${x + radius},${y}
			L${x + width - radius},${y}
			Q${x + width},${y} ${x + width},${y + radius}
			L${x + width},${y + height + bottomExtension}
			Z`;
};

/**
 * @typedef BarProps
 * @property {string} fill
 * @property {number} x
 * @property {number} y
 * @property {number} width
 * @property {number} height
 */

/**
 * @param {import('recharts').BarProps} props
 */
export const BottomBar = (props) => {
	const { fill, x, y, width, height } = props;

	return (
		<path
			d={getBarPath({
				isTop: false,
				x: Number(x),
				y: Number(y),
				width: Number(width),
				height: Number(height),
			})}
			stroke="none"
			fill={fill}
		/>
	);
};

/**
 * @param {import('recharts').BarProps} props
 */
export const TopBar = (props) => {
	const { fill, x, y, width, height } = props;

	return (
		<path
			d={getBarPath({
				isTop: true,
				x: Number(x),
				y: Number(y),
				width: Number(width),
				height: Number(height),
			})}
			stroke="none"
			fill={fill}
		/>
	);
};
```

**Behavior/SVG math:** Used as `shape` overrides for recharts `<Bar>` in a stacked bar chart (`stackId="a"`), giving only the *top* bar segment rounded top corners (radius `4`) while the bottom segment stays square, and letting the top segment "bleed" 6px lower than its box (`bottomExtension = isTop ? 6 : 0`) so the two stacked bar segments visually overlap/connect seamlessly with no gap/seam line at the stack boundary. Path: starts at bottom-left (`x, y+height+bottomExtension`), draws straight up to `y+radius`, quadratic-curves to the top-left rounded corner, straight across the top to `x+width-radius`, quadratic-curves to the top-right rounded corner, straight down the right edge to `y+height+bottomExtension`, and closes. Both `TopBar`/`BottomBar` render as `<path>` with `stroke="none"` and `fill={fill}` (fill supplied via the `<Bar fill={...}>` prop from the parent chart, i.e. `TopBar`/`BottomBar` don't hardcode colors themselves).

## 8. `src/components/RamUsageGraph/RamUsageGraph.tsx` (full file)

```tsx
import React, { useMemo, useState } from 'react';

import {
	Area,
	AreaChart,
	CartesianGrid,
	ResponsiveContainer,
	Tooltip,
	XAxis,
	YAxis,
} from 'recharts';

import Box from '@liquidweb-dev/undercurrent/Box';
import Skeleton from '@liquidweb-dev/undercurrent/Skeleton';
import Typography from '@liquidweb-dev/undercurrent/Typography';
import { useTheme } from '@liquidweb-dev/undercurrent';
import makeGraphData from 'modules/queries/asset/measurements/makeGraphData';
import useAssetMeasurementsLookup from 'modules/queries/asset/measurements/useLookup';
import useAssetDetails from 'modules/queries/asset/useDetails';
import StatHighlight from 'components/Graphs/StatHighlight';
import GraphSkeleton from 'components/Graphs/GraphSkeleton';
import GraphTimeTooltip from 'components/Graphs/GraphTimeTooltip';
import GraphCard, { type GraphCardProps } from 'components/Graphs/GraphCard';
import { Empty, Error, Loading } from 'components/Graphs/GraphStateCard';
import {
	avg,
	changeColorForIncrease,
	changeResultToStatHighlightProps,
	computeChange,
	DOUBLED_DURATION,
	periodChange,
	type Duration,
} from 'components/Graphs/graphMeasurements';
import hostingDetailsAlsowith from 'pages/servers/details/hostingDetailsAlsowith';
import formatBytes from 'utility/formatBytes';
import { type CardProps } from '@liquidweb-dev/undercurrent/Card';

export interface RamUsageGraphProps extends CardProps {
	uniqId: string;
}

const DURATION: Duration = '12hour';

/** Card header config shared by the populated card and the loading/error/empty states. */
const CARD: Pick<GraphCardProps, 'title' | 'infoTooltip'> = {
	title: 'RAM usage',
};

const RamUsageGraph = ({ uniqId, ...rest }: RamUsageGraphProps) => {
	const [activeIndex, setActiveIndex] = useState<number | null>(null);
	const theme = useTheme();

	const { data: assetDetails } = useAssetDetails({
		uniq_id: uniqId,
		alsowith: hostingDetailsAlsowith,
	});

	const {
		data: memoryData,
		isLoading,
		isPreviousData,
		isError,
		refetch,
	} = useAssetMeasurementsLookup(
		{
			uniq_id: uniqId,
			name: 'memory',
			fields: ['used'],
			// Fetch double the display window so we can compare current vs previous period.
			duration: DOUBLED_DURATION[DURATION] ?? DURATION,
		},
		{ keepPreviousData: true },
	);

	const allData = useMemo(
		() => makeGraphData({ data: memoryData?.data, keys: ['memory'] }),
		[memoryData],
	);

	if (isLoading && !isPreviousData)
		return (
			<Loading {...CARD} {...rest}>
				<Box
					sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}
				>
					<Skeleton variant="text" sx={{ width: '140px', height: '48px' }} />
					<Skeleton variant="text" sx={{ width: '160px', height: '16px' }} />
				</Box>
				<GraphSkeleton />
			</Loading>
		);
	if (isError) return <Error {...CARD} onTryAgain={refetch} {...rest} />;
	if (allData.length === 0) return <Empty {...CARD} {...rest} />;

	// Split at midpoint: first half = previous period, second half = current period.
	const midpoint = Math.floor(allData.length / 2);
	const prevData = allData.slice(0, midpoint);
	const graphData = allData.slice(midpoint);

	const currentAvg = avg(graphData, 'memory');
	const prevAvg = avg(prevData, 'memory');

	// Period-over-period % change: current avg vs previous period avg.
	const periodChangePercent = periodChange(currentAvg, prevAvg);

	// When hovering: show point value + point-to-previous change.
	// When not hovering: show period avg + period-over-period change.
	const isHovering = activeIndex !== null;
	const displayIndex = isHovering ? activeIndex : graphData.length - 1;
	const displayPoint = graphData[displayIndex];
	const displayBytes = displayPoint?.memory ?? 0;
	const changePercent = isHovering
		? computeChange(graphData, 'memory', displayIndex)
		: periodChangePercent;

	/** RAM is in MB from asset details; convert to bytes for consistent formatting */
	const totalRamMb =
		typeof assetDetails?.ram === 'number' ? assetDetails.ram : null;
	const totalRamBytes = totalRamMb ? totalRamMb * 1024 * 1024 : null;

	const usedFormatted = formatBytes(displayBytes, 1, 'GB');
	const totalFormatted = totalRamBytes
		? formatBytes(totalRamBytes, 0, 'GB')
		: null;

	const percentUsed =
		totalRamBytes && totalRamBytes > 0
			? Math.round((displayBytes / totalRamBytes) * 100)
			: null;

	const changeColor = changeColorForIncrease(changePercent, theme);

	// value is always the % (or raw number if no total); unit carries the GB reading.
	const displayValue =
		percentUsed !== null ? `${percentUsed}%` : `${usedFormatted.raw}`;
	const avgSuffix = isHovering ? '' : ' avg';
	const unitLabel = totalFormatted
		? `${usedFormatted.raw}/${totalFormatted.raw} GB${avgSuffix}`
		: `${usedFormatted.unit}${avgSuffix}`;

	return (
		<GraphCard {...CARD} {...rest}>
			{/* Stats area — 16px padding, 12px gap between elements */}
			<Box
				sx={{
					display: 'flex',
					flexDirection: 'column',
					p: 200,
					gap: 150,
				}}
			>
				{/* Highlight */}
				<StatHighlight
					value={displayValue}
					unit={unitLabel}
					{...changeResultToStatHighlightProps(changePercent)}
					changeColor={changeColor}
				/>

				{/* Secondary stats — swap row (hardcoded placeholder) */}
				<Box
					sx={{
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'space-between',
					}}
				>
					<Box sx={{ display: 'flex', alignItems: 'center', gap: 50 }}>
						<Typography
							fontType="monospace"
							variant="label-sm"
							sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
						>
							Swap
						</Typography>
						<Typography
							fontType="monospace"
							variant="label-sm"
							sx={({ vars }) => ({
								color: vars.palette.uc.warning.text.main,
								fontWeight: 600,
							})}
						>
							1.2 of 4 GB
						</Typography>
					</Box>
					<Typography
						fontType="monospace"
						variant="label-sm"
						sx={({ vars }) => ({ color: vars.palette.uc.warning.text.main })}
					>
						Monitor closely
					</Typography>
				</Box>
			</Box>

			{/* Graph — full bleed */}
			<Box sx={{ flexGrow: 1, pt: 200 }}>
				<ResponsiveContainer width="100%" height="100%">
					<AreaChart
						data={graphData}
						margin={{ top: 0, right: 0, left: 0, bottom: 0 }}
						onMouseMove={(state) => {
							if (state.isTooltipActive && state.activeTooltipIndex != null) {
								setActiveIndex(state.activeTooltipIndex);
							}
						}}
						onMouseLeave={() => setActiveIndex(null)}
					>
						<CartesianGrid vertical={false} strokeDasharray="5 5" />
						<XAxis
							type="number"
							hide
							dataKey="time"
							scale="time"
							domain={['dataMin', 'dataMax']}
							interval={graphData.length > 10 ? 'equidistantPreserveStart' : 0}
						/>
						<YAxis
							hide
							domain={[
								0,
								(dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.05),
							]}
						/>
						<Tooltip content={<GraphTimeTooltip duration={DURATION} />} />
						{/* TODO: one-off data colors until UC adds themeable data-color tokens. */}
						<Area
							dot={false}
							dataKey="memory"
							type="monotone"
							stroke="#9100FF"
							strokeWidth={2}
							fill="#E9CCFF"
							animationDuration={500}
							name="Memory"
						/>
					</AreaChart>
				</ResponsiveContainer>
			</Box>
		</GraphCard>
	);
};

export default RamUsageGraph;
```

**Hover logic detail (this is the pattern shared by all charts):** `activeIndex` state is set from recharts' `onMouseMove` callback — `state.activeTooltipIndex` — only when `state.isTooltipActive` is true, and cleared on `onMouseLeave`. When `activeIndex !== null` (`isHovering`), the StatHighlight switches from the period average + period-over-period change to the specific hovered point's value + point-to-previous-point change (`computeChange`). Colors: stroke `#9100FF` (purple), fill `#E9CCFF` (light purple), `strokeWidth={2}`, `dot={false}`, `type="monotone"`, `animationDuration={500}`. `XAxis`/`YAxis` are both `hide`; `YAxis` domain is `[0, dataMax*1.05]` (or 1 if dataMax is 0). `CartesianGrid` is `vertical={false}` with `strokeDasharray="5 5"` (dashed horizontal-only background grid).

