import { Empty, Error, Loading } from 'components/Graphs/GraphStateCard';
import {
	avg,
	changeResultToStatHighlightProps,
	computeChange,
	DOUBLED_DURATION,
	periodChange,
	type Duration,
} from 'components/Graphs/graphMeasurements';

export interface BandwidthUsageGraphProps extends CardProps {
	uniqId: string;
}

// Bandwidth card always shows the full monthly window — the range selector
// lives at the page level, not within this module.
const DURATION: Duration = 'month';

// TODO: one-off data colors until UC adds themeable data-color tokens.
const TOTAL_COLOR = '#EC4899';

/** Card header config shared by the populated card and the loading/error/empty states. */
const CARD: Pick<GraphCardProps, 'title'> = {
	title: 'Bandwidth',
};

/** Format MB to a human-readable value + unit string. */
const formatMB = (mb: number): { value: string; unit: string } => {
	if (mb >= 1000) {
		return { value: (mb / 1000).toFixed(2), unit: 'GB' };
	}
	return { value: mb.toFixed(2), unit: 'MB' };
};

const BandwidthUsageGraph = ({ uniqId, ...rest }: BandwidthUsageGraphProps) => {
	const [activeIndex, setActiveIndex] = useState<number | null>(null);
	const theme = useTheme();
	const incomingColor = theme.vars.palette.uc.highlight.bg.medium;
	const outgoingColor = theme.vars.palette.uc.highlight.bg.strong;

	const {
		data: rawData,
		isLoading,
		isPreviousData,
		isError,
		refetch,
	} = useAssetMeasurementsLookup(
		{
			uniq_id: uniqId,
			// TODO: confirm measurement name and field names with backend
			name: 'bandwidth',
			fields: ['incoming', 'outgoing'],
			// Fetch double the display window so we can compare current vs previous period.
			duration: DOUBLED_DURATION[DURATION] ?? DURATION,
		},
		{ keepPreviousData: true },
	);

	const allData = useMemo(
		() =>
			makeGraphData({
				data: rawData?.data,
				keys: ['incoming', 'outgoing'],
			}) as Array<{ time: number; incoming: number; outgoing: number }>,
		[rawData],
	);

	if (isLoading && !isPreviousData)
		return (
			<Loading {...CARD} {...rest}>
				<Box
					sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}
				>
					<Box sx={{ display: 'flex', gap: 400 }}>
						<Skeleton variant="text" sx={{ width: '100px', height: '48px' }} />
						<Skeleton variant="text" sx={{ width: '100px', height: '48px' }} />
						<Skeleton variant="text" sx={{ width: '100px', height: '48px' }} />
					</Box>
				</Box>
				<GraphSkeleton />
			</Loading>
		);
	if (isError) return <Error {...CARD} onTryAgain={refetch} {...rest} />;
	if (allData.length === 0) return <Empty {...CARD} {...rest} />;

	// Split at midpoint: first half = previous period, second half = current period.
	const midpoint = Math.floor(allData.length / 2);
	const prevData = allData.slice(0, midpoint);
	const graphData = allData.slice(midpoint);

	// Cumulative total must be scoped to the current period only, not the doubled fetch window.
	let cumulative = 0;
	const chartData = graphData.map((p) => {
		cumulative += (p.incoming ?? 0) + (p.outgoing ?? 0);
		return { ...p, totalCumulative: cumulative };
	});

	// Default: period average. While hovering: the hovered point's value.
	const isHovering = activeIndex !== null;
	const avgIncoming = avg(graphData, 'incoming');
	const avgOutgoing = avg(graphData, 'outgoing');
	const prevAvgIncoming = avg(prevData, 'incoming');
	const prevAvgOutgoing = avg(prevData, 'outgoing');

	const displayIndex = activeIndex ?? chartData.length - 1;
	const displayPoint = chartData[displayIndex];

	const displayIncoming = isHovering
		? (displayPoint?.incoming ?? 0)
		: avgIncoming;
	const displayOutgoing = isHovering
		? (displayPoint?.outgoing ?? 0)
		: avgOutgoing;

	const periodIncomingChange = periodChange(avgIncoming, prevAvgIncoming);
	const incomingChange = isHovering
		? computeChange(graphData, 'incoming', displayIndex)
		: periodIncomingChange;

	const periodOutgoingChange = periodChange(avgOutgoing, prevAvgOutgoing);
	const outgoingChange = isHovering
		? computeChange(graphData, 'outgoing', displayIndex)
		: periodOutgoingChange;

	// Total used reflects the cumulative at the hovered point, not always period-end.
	const totalUsedMB = displayPoint?.totalCumulative ?? 0;
	const formattedIncoming = formatMB(displayIncoming);
	const formattedOutgoing = formatMB(displayOutgoing);
	const formattedTotal = formatMB(totalUsedMB);

	return (
		<GraphCard {...CARD} {...rest}>
			<Box sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}>
				{/* Three StatHighlights in a row */}
				<Box
					sx={{
						display: 'flex',
						flexWrap: 'wrap',
						gap: 400,
						alignItems: 'flex-start',
					}}
				>
					<StatHighlight
						label="Incoming"
						iconColor={incomingColor}
						value={formattedIncoming.value}
						unit={formattedIncoming.unit}
						{...changeResultToStatHighlightProps(incomingChange)}
					/>
					<StatHighlight
						label="Outgoing"
						iconColor={outgoingColor}
						value={formattedOutgoing.value}
						unit={formattedOutgoing.unit}
						{...changeResultToStatHighlightProps(outgoingChange)}
					/>
					<StatHighlight
						label="Total used"
						iconColor={TOTAL_COLOR}
						value={formattedTotal.value}
						unit={formattedTotal.unit}
					/>
				</Box>
			</Box>

			{/* Chart — full bleed */}
			<Box sx={{ flexGrow: 1, pt: 200 }}>
				<ResponsiveContainer width="100%" height="100%">
					<ComposedChart
						data={chartData}
						margin={{ top: 0, right: 0, left: 0, bottom: 0 }}
						maxBarSize={32}
						reverseStackOrder
						onMouseMove={(state) => {
							if (state.isTooltipActive && state.activeTooltipIndex != null) {
								setActiveIndex(state.activeTooltipIndex);
							}
						}}
						onMouseLeave={() => setActiveIndex(null)}
					>
						<CartesianGrid vertical={false} strokeDasharray="5 5" />
						<XAxis
							type="number"
							hide
							dataKey="time"
							scale="time"
							domain={['dataMin', 'dataMax']}
							interval={graphData.length > 10 ? 'equidistantPreserveStart' : 0}
						/>
						{/* Left axis for stacked bars, right axis for cumulative line — keeps both visible at their own scale. */}
						<YAxis
							yAxisId="bars"
							hide
							domain={[
								0,
								(dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.05),
							]}
						/>
						<YAxis
							yAxisId="cumulative"
							orientation="right"
							hide
							domain={[
								0,
								(dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.1),
							]}
						/>
						<Tooltip content={<GraphTimeTooltip duration={DURATION} />} />
						<Bar
							yAxisId="bars"
							name="Incoming"
							dataKey="incoming"
							fill={incomingColor}
							animationDuration={500}
							stackId="a"
							shape={<TopBar dataKey="incoming" />}
						/>
						<Bar
							yAxisId="bars"
							name="Outgoing"
							dataKey="outgoing"
							fill={outgoingColor}
							animationDuration={500}
							stackId="a"
							shape={<BottomBar dataKey="outgoing" />}
						/>
						{/* TODO: one-off color for cumulative line until UC adds themeable data-color tokens. */}
						<Line
							yAxisId="cumulative"
							dot={false}
							dataKey="totalCumulative"
							type="monotone"
							stroke={TOTAL_COLOR}
							strokeWidth={2}
							animationDuration={500}
							name="Total used"
						/>
					</ComposedChart>
				</ResponsiveContainer>
			</Box>
		</GraphCard>
	);
};

export default BandwidthUsageGraph;
```

**Notes:** Uses `ComposedChart` with a stacked `Bar` pair (`stackId="a"`, `maxBarSize={32}`, `reverseStackOrder`) using the custom `TopBar`/`BottomBar` shapes from `Bars.jsx`, plus a `Line` overlay for cumulative total on a secondary right-side `yAxisId="cumulative"` Y-axis (dual-axis chart). Colors: `incomingColor = theme.vars.palette.uc.highlight.bg.medium`, `outgoingColor = theme.vars.palette.uc.highlight.bg.strong` (theme tokens, not hardcoded hex), `TOTAL_COLOR = '#EC4899'` (pink, hardcoded, for cumulative line + "Total used" stat icon dot).

