88	## 3. `src/components/Graphs/StatHighlight/StatHighlight.tsx`
89	
90	```tsx
91	import Box, { type BoxProps } from '@liquidweb-dev/undercurrent/Box';
92	import Typography from '@liquidweb-dev/undercurrent/Typography';
93	import TrendingUpIcon from '@liquidweb-dev/undercurrent/icons/lucide/TrendingUp';
94	import TrendingDownIcon from '@liquidweb-dev/undercurrent/icons/lucide/TrendingDown';
95	import combineSx from '@liquidweb-dev/undercurrent/utility/combineSx';
96	
97	export interface StatHighlightProps extends BoxProps {
98		/** Monospace label shown above the value, e.g. "1 min". Omit when the card header serves as the label. */
99		label?: string;
100		/**
101		 * Full formatted value string including any short suffix, e.g. "64%", "75%", "3.8".
102		 * Do NOT use unit= for %; unit= is for longer secondary values like "14.2/16 GB".
103		 */
104		value: string;
105		/** Optional secondary value shown in the extras column, e.g. "14.2/16 GB". */
106		unit?: string;
107		/** Optional % change. Positive = up, negative = down. */
108		changePercent?: number;
109		/**
110		 * Optional custom change label rendered instead of "±N%", e.g. "+1.5 GB/day".
111		 * When provided, changePercent is not required — use changeDirection to control the icon.
112		 */
113		changeLabel?: string;
114		/**
115		 * Explicit icon direction when changeLabel is used without changePercent.
116		 * Defaults to 'up' when changePercent >= 0.
117		 */
118		changeDirection?: 'up' | 'down';
119		/**
120		 * Color applied to the percent change icon and text. Defaults to text.weak.
121		 * Pass a resolved CSS color for semantic meaning, e.g. vars.palette.uc.success.text.main.
122		 */
123		changeColor?: string;
124		/** Optional 12×12 rounded-square color key shown in the label row (Load Average series). */
125		iconColor?: string;
126		/**
127		 * Override color for the large value. Defaults to text.main.
128		 * Pass a resolved CSS color, e.g. vars.palette.uc.danger.text.main for critical states.
129		 */
130		valueColor?: string;
131	}
132	
133	/**
134	 * Stat highlight matching the Figma "Highlight" component spec.
135	 * Layout: label row → score row (large value + extras column).
136	 */
137	const StatHighlight = ({
138		label,
139		value,
140		unit,
141		changePercent,
142		changeLabel,
143		changeDirection,
144		changeColor,
145		iconColor,
146		valueColor,
147		sx,
148		...rest
149	}: StatHighlightProps) => {
150		const hasChange =
151			(changePercent !== undefined && changePercent !== null) ||
152			Boolean(changeLabel);
153		// changeDirection wins; fall back to sign of changePercent; default to up when neither is set
154		const isPositive =
155			changeDirection === 'up' ||
156			(changeDirection === undefined &&
157				(changePercent !== undefined ? changePercent >= 0 : true));
158		const hasExtras = Boolean(unit) || hasChange;
159	
160		return (
161			<Box
162				sx={combineSx({ display: 'flex', flexDirection: 'column', gap: 100 }, sx)}
163				{...rest}
164			>
165				{/* Label row — only rendered when label or iconColor is provided */}
166				{(label || iconColor) && (
167					<Box sx={{ display: 'flex', alignItems: 'center', gap: 100 }}>
168						{iconColor && (
169							<Box
170								sx={({ size, borderRadius }) => ({
171									width: size.xXS,
172									height: size.xXS,
173									borderRadius: borderRadius.roundedSm,
174									backgroundColor: iconColor,
175									flexShrink: 0,
176								})}
177							/>
178						)}
179						<Typography
180							fontType="monospace"
181							variant="label-md"
182							sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
183						>
184							{label}
185						</Typography>
186					</Box>
187				)}
188	
189				{/* Score row */}
190				<Box
191					sx={{
192						display: 'flex',
193						alignItems: 'flex-end',
194						gap: 100,
195						width: '100%',
196					}}
197				>
198					{/* Large value */}
199					{/* TODO: hardcoded scale pending a typographic-scale decision; replace with a UC variant before release. */}
200					<Typography
201						sx={({ vars }) => ({
202							fontSize: '40px',
203							lineHeight: '38px',
204							letterSpacing: '-0.64px',
205							color: valueColor ?? vars.palette.uc.text.main,
206							whiteSpace: 'nowrap',
207						})}
208					>
209						{value}
210					</Typography>
211	
212					{/* Extras column — unit + % change stacked */}
213					{hasExtras && (
214						<Box
215							sx={{
216								display: 'flex',
217								flexDirection: 'column',
218								alignItems: 'flex-start',
219								justifyContent: 'flex-end',
220								gap: 50,
221							}}
222						>
223							{unit && (
224								<Typography
225									fontType="monospace"
226									variant="label-md"
227									sx={({ vars }) => ({
228										color: vars.palette.uc.text.weak,
229										whiteSpace: 'nowrap',
230									})}
231								>
232									{unit}
233								</Typography>
234							)}
235	
236							{hasChange && (
237								<Box
238									sx={({ vars }) => ({
239										display: 'flex',
240										alignItems: 'center',
241										gap: 50,
242										color: changeColor ?? vars.palette.uc.text.weak,
243									})}
244								>
245									{isPositive ? (
246										<TrendingUpIcon
247											sx={({ size }) => ({ width: size.xS, height: size.xS })}
248										/>
249									) : (
250										<TrendingDownIcon
251											sx={({ size }) => ({ width: size.xS, height: size.xS })}
252										/>
253									)}
254									<Typography fontType="monospace" variant="label-md">
255										{changeLabel ??
256											`${isPositive ? '+' : '-'}${Math.abs(changePercent ?? 0)}%`}
257									</Typography>
258								</Box>
259							)}
260						</Box>
261					)}
262				</Box>
263			</Box>
264		);
265	};
266	
267	export default StatHighlight;
268	```
269	
270	**Behavior:** Two-row layout — optional label row (monospace weak-color text + optional 12×12 `roundedSm` color swatch via `iconColor`), then a score row with a large 40px/38px-line-height/-0.64px-letter-spacing value, and an "extras" column stacked to the right containing an optional `unit` (monospace, weak color) and an optional change indicator (Trending Up/Down lucide icon + monospace text, colored via `changeColor`, default `text.weak`). Change text defaults to `±N%` from `changePercent`, or a custom `changeLabel` string (e.g., "+1.5 GB/day", "New"). Direction/icon chosen by `changeDirection` if given, else sign of `changePercent`, defaulting to "up".
