366	## 5. `src/components/Graphs/graphMeasurements.ts`
367	
368	```ts
369	import type { Theme } from '@mui/material/styles';
370	import type { LWApiPublicAssetMeasurementsLookupParamsRawI } from '@liquidweb-dev/club-sauce/public/asset/measurements/index.raw';
371	import { type StatHighlightProps } from 'components/Graphs/StatHighlight';
372	
373	/** Measurement lookup duration window (e.g. '12hour', 'day', '2week'). */
374	export type Duration = LWApiPublicAssetMeasurementsLookupParamsRawI['duration'];
375	
376	/**
377	 * Result of a change computation: a rounded percent, `'new'` when the previous
378	 * period/point was a genuine zero and the current value is positive (a real
379	 * signal, not a percentage), or undefined when unknown or flat.
380	 */
381	export type ChangeResult = number | 'new' | undefined;
382	
383	/** dayjs format string for tooltip timestamps — date for long windows, time otherwise. */
384	export const tooltipDateFormat = (duration: Duration) =>
385		duration === '2week' ? 'MMM D, YYYY' : 'h:mm a';
386	
387	/**
388	 * Maps each display duration to a doubled window so we can fetch the previous
389	 * period alongside the current one and compute period-over-period change.
390	 * TODO: the doubled values here (e.g. day -> 3day, month -> 3month) need review;
391	 * this comparison will ultimately move to the backend API.
392	 */
393	export const DOUBLED_DURATION: Partial<Record<Duration, Duration>> = {
394		'6hour': '12hour',
395		'12hour': 'day',
396		day: '3day',
397		'2week': 'month',
398		month: '3month',
399	} as const;
400	
401	/** Mean of `key` across data points that have a value; skips null/missing readings. */
402	export const avg = (data: Array<Record<string, number>>, key: string) => {
403		const present = data.filter((p) => p[key] != null);
404		if (!present.length) return 0;
405		return present.reduce((sum, p) => sum + p[key], 0) / present.length;
406	};
407	
408	/**
409	 * Point-to-previous-point percentage change for `key` at `index`.
410	 * Returns undefined for the first point or when either value is missing.
411	 * Returns 'new' when the previous point was a genuine zero and the current
412	 * point is positive, rather than hiding the spike as "unknown".
413	 */
414	export const computeChange = (
415		data: Array<Record<string, number>>,
416		key: string,
417		index: number,
418	): ChangeResult => {
419		if (index < 1) return undefined;
420		const current = data[index][key];
421		const previous = data[index - 1][key];
422		if (current == null || previous == null) return undefined;
423		if (previous === 0) return current > 0 ? 'new' : undefined;
424		return Math.round(((current - previous) / previous) * 100);
425	};
426	
427	/**
428	 * Period-over-period percentage change between a current and previous average.
429	 * See ChangeResult for the 'new'-baseline sentinel.
430	 */
431	export const periodChange = (
432		currentAvg: number,
433		prevAvg: number,
434	): ChangeResult => {
435		if (prevAvg === 0) return currentAvg > 0 ? 'new' : undefined;
436		return Math.round(((currentAvg - prevAvg) / prevAvg) * 100);
437	};
438	
439	/** Danger for an increase (including 'new'), success for a decrease; undefined when change is flat or unknown. */
440	export const changeColorForIncrease = (
441		changePercent: ChangeResult,
442		theme: Theme,
443	) => {
444		if (changePercent === undefined) return undefined;
445		if (changePercent === 'new' || changePercent > 0)
446			return theme.vars.palette.uc.danger.text.main;
447		if (typeof changePercent === 'number' && changePercent < 0)
448			return theme.vars.palette.uc.success.text.main;
449		return undefined;
450	};
451	
452	/** Maps a ChangeResult to the StatHighlight props that render it. */
453	export const changeResultToStatHighlightProps = (
454		change: ChangeResult,
455	): Pick<
456		StatHighlightProps,
457		'changePercent' | 'changeLabel' | 'changeDirection'
458	> => {
459		if (change === 'new') return { changeLabel: 'New', changeDirection: 'up' };
460		if (change === undefined) return {};
461		return { changePercent: change };
462	};
463	```
464	
465	**Behavior:** Shared math/formatting utilities. `tooltipDateFormat` — the key detail: `'2week'` duration → `'MMM D, YYYY'` (e.g. "May 9, 2026"); every other duration → `'h:mm a'` (e.g. "2:30 pm"). `DOUBLED_DURATION` maps a display window to a "fetch double, split at midpoint" window used by all the charts to compute period-over-period change. `avg`, `computeChange` (point-to-previous-point %), `periodChange` (avg-vs-avg %), `changeColorForIncrease` (danger red if increase/new, success green if decrease), and `changeResultToStatHighlightProps` (adapts a `ChangeResult` into `StatHighlight` props, turning `'new'` into a `changeLabel: 'New'`).
