1126		projectedFullTs?: number | null;
1127	}
1128	
1129	const WARNING_THRESHOLD = 75;
1130	const CRITICAL_THRESHOLD = 90;
1131	
1132	const GROWTH_WARNING_THRESHOLD = 1.5; // GB/day
1133	const GROWTH_CRITICAL_THRESHOLD = 3; // GB/day
1134	
1135	/** Card header config shared by the populated card and the loading/error/empty states. */
1136	const CARD: Pick<GraphCardProps, 'title'> = {
1137		title: 'Disk space',
1138	};
1139	
1140	const DiskSpaceGraph = ({
1141		uniqId,
1142		growthGBday,
1143		projectedDaysLeft,
1144		projectedFullTs,
1145		...rest
1146	}: DiskSpaceGraphProps) => {
1147		const theme = useTheme();
1148	
1149		const {
1150			data: assetDetails,
1151			isLoading,
1152			isError,
1153			refetch,
1154		} = useAssetDetails({
1155			uniq_id: uniqId,
1156			alsowith: hostingDetailsAlsowith,
1157		});
1158	
1159		if (isLoading)
1160			return (
1161				<Loading {...CARD} {...rest}>
1162					<Box
1163						sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}
1164					>
1165						<Skeleton variant="text" sx={{ width: '80px', height: '48px' }} />
1166						<Skeleton variant="text" sx={{ width: '160px', height: '16px' }} />
1167						<Skeleton
1168							variant="rectangular"
1169							sx={({ size }) => ({ width: '100%', height: size.xS })}
1170						/>
1171					</Box>
1172				</Loading>
1173			);
1174		if (isError) return <Error {...CARD} onTryAgain={refetch} {...rest} />;
1175	
1176		// Extract disk.lvm.volume from resourceState, subtracting snapshot reservation
1177		const diskEntry = assetDetails?.resourceState?.find(
1178			(v) => v.type === 'disk.lvm.volume',
1179		);
1180	
1181		if (!diskEntry) return <Empty {...CARD} {...rest} />;
1182	
1183		// snapshots is in bytes (same unit as diskEntry.used/total) — confirmed via useDetails.ts getParentDiskResources
1184		const snapshots = assetDetails?.diskDetails?.snapshots ?? 0;
1185		const usedBytes = Number(diskEntry.used) - snapshots;
1186		const totalBytes = Number(diskEntry.total) - snapshots;
1187	
1188		if (totalBytes <= 0) return <Empty {...CARD} {...rest} />;
1189	
1190		const percentUsed = Math.round((usedBytes / totalBytes) * 100);
1191		const usedFormatted = formatBytes(usedBytes, 1, 'GB');
1192		const totalFormatted = formatBytes(totalBytes, 0, 'GB');
1193		const unitLabel = `${usedFormatted.raw}/${totalFormatted.raw} GB`;
1194	
1195		const isCritical = percentUsed >= CRITICAL_THRESHOLD;
1196		const isWarning = percentUsed >= WARNING_THRESHOLD;
1197	
1198		// Danger red when critical, warning amber when approaching — disk high usage is bad
1199		let statColor: string | undefined;
1200		if (isCritical) {
1201			statColor = theme.vars.palette.uc.danger.text.main;
1202		} else if (isWarning) {
1203			statColor = theme.vars.palette.uc.warning.text.main;
1204		}
1205	
1206		// Growth rate label shown in StatHighlight extras column (e.g. "+1.5 GB/day")
1207		const changeLabel =
1208			growthGBday != null ? `+${growthGBday.toFixed(1)} GB/day` : undefined;
1209	
1210		// Growth rate color: neutral by default, escalates to warning/danger at thresholds
1211		let changeColor: string | undefined;
1212		if (growthGBday != null && growthGBday >= GROWTH_CRITICAL_THRESHOLD) {
1213			changeColor = theme.vars.palette.uc.danger.text.main;
1214		} else if (growthGBday != null && growthGBday >= GROWTH_WARNING_THRESHOLD) {
1215			changeColor = theme.vars.palette.uc.warning.text.main;
1216		}
1217	
1218		const footerBgcolor = isCritical
1219			? theme.vars.palette.uc.danger.bg.main
1220			: undefined;
1221	
1222		const footerContent =
1223			projectedFullTs != null && projectedDaysLeft != null ? (
1224				<Typography variant="label-md">
1225					<Box
1226						component="span"
1227						sx={({ vars }) => ({
1228							fontWeight: 700,
1229							color: isCritical
1230								? vars.palette.uc.danger.text.main
1231								: vars.palette.uc.text.weak,
1232						})}
1233					>
1234						{`Full by ${dayjs.unix(projectedFullTs).format('MMM D, YYYY')}`}
1235					</Box>
1236					<Box
1237						component="span"
1238						sx={({ vars }) => ({ color: vars.palette.uc.text.medium })}
1239					>
1240						{` · ${Math.ceil(projectedDaysLeft)} days left`}
1241					</Box>
1242				</Typography>
1243			) : (
1244				<Typography
1245					variant="label-md"
1246					sx={({ vars }) => ({
1247						fontWeight: 700,
1248						color: vars.palette.uc.text.weak,
1249					})}
1250				>
1251					—
1252				</Typography>
1253			);
1254	
1255		return (
1256			<GraphCard
1257				{...CARD}
1258				footer={footerContent}
1259				footerBgcolor={footerBgcolor}
1260				{...rest}
1261			>
1262				<Box
1263					sx={{
1264						display: 'flex',
1265						flexDirection: 'column',
1266						gap: 150,
1267						p: 200,
1268					}}
1269				>
1270					<StatHighlight
1271						value={`${percentUsed}%`}
1272						valueColor={statColor}
1273						unit={unitLabel}
1274						changeLabel={changeLabel}
1275						changeDirection="up"
1276						changeColor={changeColor}
1277					/>
1278	
1279					<MeasureBar
1280						percentage={percentUsed}
1281						hidePercentage
1282						warningThreshold={WARNING_THRESHOLD}
1283						criticalThreshold={CRITICAL_THRESHOLD}
1284						sx={({ size }) => ({ height: size.xL })}
1285					/>
1286				</Box>
1287			</GraphCard>
1288		);
1289	};
1290	
1291	export default DiskSpaceGraph;
1292	```
1293	
1294	**Important note:** DiskSpaceGraph does NOT use recharts at all — it's a `StatHighlight` + Undercurrent's `MeasureBar` (a horizontal fill-bar progress indicator), no chart/tooltip/hover logic. Thresholds: warning ≥75%, critical ≥90% (disk); growth-rate warning ≥1.5 GB/day, critical ≥3 GB/day.
1295	
1296	**`MeasureBar` component** (`@liquidweb-dev/undercurrent/MeasureBar/MeasureBar.js`, compiled JS — TS declaration below is the authoritative prop contract):
1297	
1298	```ts
1299	// MeasureBar.d.ts
1300	export interface MeasureBarProps extends Omit<BoxProps, 'color'> {
1301	    color?: string | ((theme: Theme) => string);
1302	    criticalThreshold?: number;
1303	    hidePercentage?: boolean;
1304	    label?: ReactNode;
1305	    orientation?: 'horizontal' | 'vertical';
1306	    percentage: number;
1307	    projected?: number;
1308	    warningThreshold?: number;
1309	    labelTypographyProps?: TypographyProps;
1310	    percentageTypographyProps?: TypographyProps;
1311	}
1312	```
1313	
1314	Compiled implementation logic (from `MeasureBar.js`, de-minified structure):
1315	- `value = clamp(percentage, 0, 100)`.
1316	- Border/fill/text color escalation: if `value >= criticalThreshold` → `theme.vars.palette.uc.danger.{border,bg,text}.main`; else if `value >= warningThreshold` → `uc.warning.{border,bg}.main` / `uc.warning.text.strong`; else → `uc.highlight.border.main` / `uc.highlight.bg.weak` / `uc.highlight.text.strong`. An explicit `color` prop (string or theme-fn) overrides the fill color specifically.
1317	- Root `Box`: `border: 1px solid` `borderColor`, `borderRadius: theme.borderRadius.rounded`, `position: relative`, `overflow: hidden`; `height: 64 / minWidth: 185` when horizontal, `height: 139 / minWidth: 138` when vertical (flex column).
1318	- "fill" `Box` (absolutely positioned, `zIndex: 1`): width = `${value}%` for horizontal (height 100% via `top:0`), or height = `${value}%` for vertical (bottom-anchored); background = `color` override or computed `fillColor`; rounded corners on the leading/outer edge only.
1319	- "projected" `Box` (absolutely positioned, no `zIndex` override, sits above fill visually via DOM order): a diagonal `repeating-linear-gradient(45deg, transparent, transparent 4px, ${borderColor}50 4px, ${borderColor}50 5px)` hatch pattern, sized by the `projected` percentage prop — this is the visual "striped" segment showing projected future growth beyond current usage.
1320	- Text `Stack` (`zIndex: 2`, on top of both fill layers): row direction (horizontal) or column-reverse (vertical), `padding: 200`, holds an optional `label` (`body-sm` typography) and (unless `hidePercentage`) the `{value}%` text (`body-sm` horizontal / `body-md` vertical).
1321	
1322	DiskSpaceGraph passes `hidePercentage` (so no `N%` shown inside the bar itself — the percent is shown via the `StatHighlight` above it instead), `warningThreshold={75}`, `criticalThreshold={90}`, and `sx={{ height: size.xL }}` to override the bar height.
1323	
