## 11. `src/components/DiskSpaceGraph/DiskSpaceGraph.tsx` (full file) + `MeasureBar`

```tsx
import dayjs from 'dayjs';
import Box from '@liquidweb-dev/undercurrent/Box';
import MeasureBar from '@liquidweb-dev/undercurrent/MeasureBar';
import Skeleton from '@liquidweb-dev/undercurrent/Skeleton';
import Typography from '@liquidweb-dev/undercurrent/Typography';
import { useTheme } from '@liquidweb-dev/undercurrent';
import { type CardProps } from '@liquidweb-dev/undercurrent/Card';

import StatHighlight from 'components/Graphs/StatHighlight';
import GraphCard, { type GraphCardProps } from 'components/Graphs/GraphCard';
import { Empty, Error, Loading } from 'components/Graphs/GraphStateCard';
import useAssetDetails from 'modules/queries/asset/useDetails';
import hostingDetailsAlsowith from 'pages/servers/details/hostingDetailsAlsowith';
import formatBytes from 'utility/formatBytes';

export interface DiskSpaceGraphProps extends CardProps {
	uniqId: string;
	/** Growth rate in GB/day from nx-monitor — optional until API is integrated app-wide */
	growthGBday?: number | null;
	/** Projected days until full from nx-monitor */
	projectedDaysLeft?: number | null;
	/** Unix timestamp (seconds) of projected full date from nx-monitor */
	projectedFullTs?: number | null;
}

const WARNING_THRESHOLD = 75;
const CRITICAL_THRESHOLD = 90;

const GROWTH_WARNING_THRESHOLD = 1.5; // GB/day
const GROWTH_CRITICAL_THRESHOLD = 3; // GB/day

/** Card header config shared by the populated card and the loading/error/empty states. */
const CARD: Pick<GraphCardProps, 'title'> = {
	title: 'Disk space',
};

const DiskSpaceGraph = ({
	uniqId,
	growthGBday,
	projectedDaysLeft,
	projectedFullTs,
	...rest
}: DiskSpaceGraphProps) => {
	const theme = useTheme();

	const {
		data: assetDetails,
		isLoading,
		isError,
		refetch,
	} = useAssetDetails({
		uniq_id: uniqId,
		alsowith: hostingDetailsAlsowith,
	});

	if (isLoading)
		return (
			<Loading {...CARD} {...rest}>
				<Box
					sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}
				>
					<Skeleton variant="text" sx={{ width: '80px', height: '48px' }} />
					<Skeleton variant="text" sx={{ width: '160px', height: '16px' }} />
					<Skeleton
						variant="rectangular"
						sx={({ size }) => ({ width: '100%', height: size.xS })}
					/>
				</Box>
			</Loading>
		);
	if (isError) return <Error {...CARD} onTryAgain={refetch} {...rest} />;

	// Extract disk.lvm.volume from resourceState, subtracting snapshot reservation
	const diskEntry = assetDetails?.resourceState?.find(
		(v) => v.type === 'disk.lvm.volume',
	);

	if (!diskEntry) return <Empty {...CARD} {...rest} />;

	// snapshots is in bytes (same unit as diskEntry.used/total) — confirmed via useDetails.ts getParentDiskResources
	const snapshots = assetDetails?.diskDetails?.snapshots ?? 0;
	const usedBytes = Number(diskEntry.used) - snapshots;
	const totalBytes = Number(diskEntry.total) - snapshots;

	if (totalBytes <= 0) return <Empty {...CARD} {...rest} />;

	const percentUsed = Math.round((usedBytes / totalBytes) * 100);
	const usedFormatted = formatBytes(usedBytes, 1, 'GB');
	const totalFormatted = formatBytes(totalBytes, 0, 'GB');
	const unitLabel = `${usedFormatted.raw}/${totalFormatted.raw} GB`;

	const isCritical = percentUsed >= CRITICAL_THRESHOLD;
	const isWarning = percentUsed >= WARNING_THRESHOLD;

	// Danger red when critical, warning amber when approaching — disk high usage is bad
	let statColor: string | undefined;
	if (isCritical) {
		statColor = theme.vars.palette.uc.danger.text.main;
	} else if (isWarning) {
		statColor = theme.vars.palette.uc.warning.text.main;
	}

	// Growth rate label shown in StatHighlight extras column (e.g. "+1.5 GB/day")
	const changeLabel =
		growthGBday != null ? `+${growthGBday.toFixed(1)} GB/day` : undefined;

	// Growth rate color: neutral by default, escalates to warning/danger at thresholds
	let changeColor: string | undefined;
	if (growthGBday != null && growthGBday >= GROWTH_CRITICAL_THRESHOLD) {
		changeColor = theme.vars.palette.uc.danger.text.main;
	} else if (growthGBday != null && growthGBday >= GROWTH_WARNING_THRESHOLD) {
		changeColor = theme.vars.palette.uc.warning.text.main;
	}

	const footerBgcolor = isCritical
		? theme.vars.palette.uc.danger.bg.main
		: undefined;

	const footerContent =
		projectedFullTs != null && projectedDaysLeft != null ? (
			<Typography variant="label-md">
				<Box
					component="span"
					sx={({ vars }) => ({
						fontWeight: 700,
						color: isCritical
							? vars.palette.uc.danger.text.main
							: vars.palette.uc.text.weak,
					})}
				>
					{`Full by ${dayjs.unix(projectedFullTs).format('MMM D, YYYY')}`}
				</Box>
				<Box
					component="span"
					sx={({ vars }) => ({ color: vars.palette.uc.text.medium })}
				>
					{` · ${Math.ceil(projectedDaysLeft)} days left`}
				</Box>
			</Typography>
		) : (
			<Typography
				variant="label-md"
				sx={({ vars }) => ({
					fontWeight: 700,
					color: vars.palette.uc.text.weak,
				})}
			>
				—
			</Typography>
		);

	return (
		<GraphCard
			{...CARD}
			footer={footerContent}
			footerBgcolor={footerBgcolor}
			{...rest}
		>
			<Box
				sx={{
					display: 'flex',
					flexDirection: 'column',
					gap: 150,
					p: 200,
				}}
			>
				<StatHighlight
					value={`${percentUsed}%`}
					valueColor={statColor}
					unit={unitLabel}
					changeLabel={changeLabel}
					changeDirection="up"
					changeColor={changeColor}
				/>

				<MeasureBar
					percentage={percentUsed}
					hidePercentage
					warningThreshold={WARNING_THRESHOLD}
					criticalThreshold={CRITICAL_THRESHOLD}
					sx={({ size }) => ({ height: size.xL })}
				/>
			</Box>
		</GraphCard>
	);
};

export default DiskSpaceGraph;
```

**Important note:** DiskSpaceGraph does NOT use recharts at all — it's a `StatHighlight` + Undercurrent's `MeasureBar` (a horizontal fill-bar progress indicator), no chart/tooltip/hover logic. Thresholds: warning ≥75%, critical ≥90% (disk); growth-rate warning ≥1.5 GB/day, critical ≥3 GB/day.

**`MeasureBar` component** (`@liquidweb-dev/undercurrent/MeasureBar/MeasureBar.js`, compiled JS — TS declaration below is the authoritative prop contract):

```ts
// MeasureBar.d.ts
export interface MeasureBarProps extends Omit<BoxProps, 'color'> {
    color?: string | ((theme: Theme) => string);
    criticalThreshold?: number;
    hidePercentage?: boolean;
    label?: ReactNode;
    orientation?: 'horizontal' | 'vertical';
    percentage: number;
    projected?: number;
    warningThreshold?: number;
    labelTypographyProps?: TypographyProps;
    percentageTypographyProps?: TypographyProps;
}
```

Compiled implementation logic (from `MeasureBar.js`, de-minified structure):
- `value = clamp(percentage, 0, 100)`.
- Border/fill/text color escalation: if `value >= criticalThreshold` → `theme.vars.palette.uc.danger.{border,bg,text}.main`; else if `value >= warningThreshold` → `uc.warning.{border,bg}.main` / `uc.warning.text.strong`; else → `uc.highlight.border.main` / `uc.highlight.bg.weak` / `uc.highlight.text.strong`. An explicit `color` prop (string or theme-fn) overrides the fill color specifically.
- Root `Box`: `border: 1px solid` `borderColor`, `borderRadius: theme.borderRadius.rounded`, `position: relative`, `overflow: hidden`; `height: 64 / minWidth: 185` when horizontal, `height: 139 / minWidth: 138` when vertical (flex column).
- "fill" `Box` (absolutely positioned, `zIndex: 1`): width = `${value}%` for horizontal (height 100% via `top:0`), or height = `${value}%` for vertical (bottom-anchored); background = `color` override or computed `fillColor`; rounded corners on the leading/outer edge only.
- "projected" `Box` (absolutely positioned, no `zIndex` override, sits above fill visually via DOM order): a diagonal `repeating-linear-gradient(45deg, transparent, transparent 4px, ${borderColor}50 4px, ${borderColor}50 5px)` hatch pattern, sized by the `projected` percentage prop — this is the visual "striped" segment showing projected future growth beyond current usage.
- Text `Stack` (`zIndex: 2`, on top of both fill layers): row direction (horizontal) or column-reverse (vertical), `padding: 200`, holds an optional `label` (`body-sm` typography) and (unless `hidePercentage`) the `{value}%` text (`body-sm` horizontal / `body-md` vertical).

DiskSpaceGraph passes `hidePercentage` (so no `N%` shown inside the bar itself — the percent is shown via the `StatHighlight` above it instead), `warningThreshold={75}`, `criticalThreshold={90}`, and `sx={{ height: size.xL }}` to override the bar height.

