## 13. `src/components/NetworkSpeedGraph/NetworkSpeedGraph.tsx` (full file) + mock data

```tsx
import { useMemo, useState } from 'react';

import {
	Area,
	AreaChart,
	CartesianGrid,
	ResponsiveContainer,
	Tooltip,
	XAxis,
	YAxis,
} from 'recharts';

import Box from '@liquidweb-dev/undercurrent/Box';
import Skeleton from '@liquidweb-dev/undercurrent/Skeleton';
import Stack from '@liquidweb-dev/undercurrent/Stack';
import Typography from '@liquidweb-dev/undercurrent/Typography';
import { type CardProps } from '@liquidweb-dev/undercurrent/Card';
import makeGraphData from 'modules/queries/asset/measurements/makeGraphData';
import useAssetMeasurementsLookup from 'modules/queries/asset/measurements/useLookup';
import StatHighlight from 'components/Graphs/StatHighlight';
import GraphSkeleton from 'components/Graphs/GraphSkeleton';
import GraphTimeTooltip from 'components/Graphs/GraphTimeTooltip';
import GraphCard, { type GraphCardProps } from 'components/Graphs/GraphCard';
import { Empty, Error, Loading } from 'components/Graphs/GraphStateCard';
import {
	avg,
	changeResultToStatHighlightProps,
	computeChange,
	DOUBLED_DURATION,
	periodChange,
	type Duration,
} from 'components/Graphs/graphMeasurements';

export interface NetworkSpeedGraphProps extends CardProps {
	uniqId: string;
}

const DURATION: Duration = '12hour';

// TODO: one-off data colors until UC adds themeable data-color tokens.
const COLORS = {
	incoming: { stroke: '#3B82F6', fill: '#EFF6FF' },
	outgoing: { stroke: '#22C55E', fill: '#DCFCE7' },
} as const;

/** Card header config shared by the populated card and the loading/error/empty states. */
const CARD: Pick<GraphCardProps, 'title' | 'infoTooltip'> = {
	title: 'Network speed',
	infoTooltip: {
		message:
			'Current network throughput — incoming and outgoing traffic per second',
		ariaLabel: 'Network speed info',
		arrow: true,
	},
};

/** Format kbps to a human-readable value + unit string. */
const formatKbps = (kbps: number): { value: string; unit: string } => {
	if (kbps >= 1000) {
		return { value: (kbps / 1000).toFixed(2), unit: 'MB/s' };
	}
	return { value: Math.round(kbps).toString(), unit: 'KB/s' };
};

/** Format kbps total to GB for the secondary stat row. */
const kbpsToGB = (kbps: number, intervalSeconds: number): number =>
	(kbps * intervalSeconds) / (8 * 1_000_000);

const NetworkSpeedGraph = ({ uniqId, ...rest }: NetworkSpeedGraphProps) => {
	const [activeIndex, setActiveIndex] = useState<number | null>(null);

	const {
		data: rawData,
		isLoading,
		isPreviousData,
		isError,
		refetch,
	} = useAssetMeasurementsLookup(
		{
			uniq_id: uniqId,
			// TODO: confirm measurement name and field names with backend
			name: 'network',
			fields: ['received', 'sent'],
			duration: DOUBLED_DURATION[DURATION] ?? DURATION,
		},
		{ keepPreviousData: true },
	);

	const allData = useMemo(
		() =>
			makeGraphData({
				data: rawData?.data,
				keys: ['received', 'sent'],
			}),
		[rawData],
	);

	if (isLoading && !isPreviousData)
		return (
			<Loading {...CARD} {...rest}>
				<Box
					sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}
				>
					<Box sx={{ display: 'flex', gap: 400 }}>
						<Skeleton variant="text" sx={{ width: '120px', height: '48px' }} />
						<Skeleton variant="text" sx={{ width: '120px', height: '48px' }} />
					</Box>
					<Skeleton variant="text" sx={{ width: '200px', height: '16px' }} />
				</Box>
				<GraphSkeleton />
			</Loading>
		);
	if (isError) return <Error {...CARD} onTryAgain={refetch} {...rest} />;
	if (allData.length === 0) return <Empty {...CARD} {...rest} />;

	// Split at midpoint: first half = previous period, second half = current period.
	const midpoint = Math.floor(allData.length / 2);
	const prevData = allData.slice(0, midpoint);

	// receivedMin/receivedMax and sentMin/sentMax come through from the mock data
	// (and eventually the /net/baseline/ API) — used directly by the band Areas.
	const graphData = allData.slice(midpoint);

	const prevAvgReceived = avg(prevData, 'received');
	const prevAvgSent = avg(prevData, 'sent');

	const isHovering = activeIndex !== null;
	const currentAvgReceived = avg(graphData, 'received');
	const currentAvgSent = avg(graphData, 'sent');

	// Default: period average. While hovering: the hovered point's instantaneous value.
	const displayIndex = isHovering ? activeIndex : graphData.length - 1;
	const displayPoint = graphData[displayIndex];
	const displayReceived = isHovering
		? (displayPoint?.received ?? 0)
		: currentAvgReceived;
	const displaySent = isHovering ? (displayPoint?.sent ?? 0) : currentAvgSent;

	const periodReceivedChange = periodChange(
		currentAvgReceived,
		prevAvgReceived,
	);
	const receivedChange = isHovering
		? computeChange(graphData, 'received', displayIndex)
		: periodReceivedChange;

	const periodSentChange = periodChange(currentAvgSent, prevAvgSent);
	const sentChange = isHovering
		? computeChange(graphData, 'sent', displayIndex)
		: periodSentChange;

	const formattedReceived = formatKbps(displayReceived);
	const formattedSent = formatKbps(displaySent);

	// Estimate total transferred up to the displayed point (hovered or latest).
	// Slicing to displayIndex + 1 makes the totals update as the user scrubs.
	const INTERVAL_SECONDS = 1800;
	const visibleData = graphData.slice(0, displayIndex + 1);
	const totalIncomingGB = visibleData
		.reduce((sum, p) => sum + kbpsToGB(p.received ?? 0, INTERVAL_SECONDS), 0)
		.toFixed(1);
	const totalOutgoingGB = visibleData
		.reduce((sum, p) => sum + kbpsToGB(p.sent ?? 0, INTERVAL_SECONDS), 0)
		.toFixed(1);

	return (
		<GraphCard {...CARD} {...rest}>
			<Box sx={{ display: 'flex', flexDirection: 'column', p: 200, gap: 150 }}>
				{/* Two StatHighlights side by side — Incoming and Outgoing */}
				<Box
					sx={{
						display: 'flex',
						flexWrap: 'wrap',
						gap: 400,
						alignItems: 'flex-start',
					}}
				>
					<StatHighlight
						label="Incoming"
						iconColor={COLORS.incoming.stroke}
						value={formattedReceived.value}
						unit={formattedReceived.unit}
						{...changeResultToStatHighlightProps(receivedChange)}
					/>
					<StatHighlight
						label="Outgoing"
						iconColor={COLORS.outgoing.stroke}
						value={formattedSent.value}
						unit={formattedSent.unit}
						{...changeResultToStatHighlightProps(sentChange)}
					/>
				</Box>

				{/* Secondary stat row: total volume transferred */}
				<Stack direction="row" sx={{ alignItems: 'center', gap: 100 }}>
					<Typography
						variant="label-sm"
						sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
					>
						Total incoming
					</Typography>
					<Typography
						fontType="monospace"
						variant="label-md"
						sx={({ vars }) => ({
							color: vars.palette.uc.text.main,
							fontWeight: 500,
						})}
					>
						{totalIncomingGB} GB
					</Typography>
					<Typography
						variant="label-sm"
						sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
					>
						·
					</Typography>
					<Typography
						variant="label-sm"
						sx={({ vars }) => ({ color: vars.palette.uc.text.weak })}
					>
						Total outgoing
					</Typography>
					<Typography
						fontType="monospace"
						variant="label-md"
						sx={({ vars }) => ({
							color: vars.palette.uc.text.main,
							fontWeight: 500,
						})}
					>
						{totalOutgoingGB} GB
					</Typography>
				</Stack>
			</Box>

			{/* Chart — full bleed */}
			<Box sx={{ flexGrow: 1, pt: 200 }}>
				<ResponsiveContainer width="100%" height="100%">
					<AreaChart
						data={graphData}
						margin={{ top: 0, right: 0, left: 0, bottom: 0 }}
						onMouseMove={(state) => {
							if (state.isTooltipActive && state.activeTooltipIndex != null) {
								setActiveIndex(state.activeTooltipIndex);
							}
						}}
						onMouseLeave={() => setActiveIndex(null)}
					>
						<CartesianGrid vertical={false} strokeDasharray="5 5" />
						<XAxis
							type="number"
							hide
							dataKey="time"
							scale="time"
							domain={['dataMin', 'dataMax']}
							interval={graphData.length > 10 ? 'equidistantPreserveStart' : 0}
						/>
						<YAxis
							hide
							domain={[
								0,
								(dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.1),
							]}
						/>
						<Tooltip content={<GraphTimeTooltip duration={DURATION} />} />
						{/* TODO: one-off data colors until UC adds themeable data-color tokens. */}
						<Area
							dot={false}
							dataKey="received"
							type="monotone"
							stroke={COLORS.incoming.stroke}
							strokeWidth={2}
							fill="none"
							animationDuration={500}
							name="Incoming"
						/>
						<Area
							dot={false}
							dataKey="sent"
							type="monotone"
							stroke={COLORS.outgoing.stroke}
							strokeWidth={2}
							fill="none"
							animationDuration={500}
							name="Outgoing"
						/>
					</AreaChart>
				</ResponsiveContainer>
			</Box>
		</GraphCard>
	);
};

export default NetworkSpeedGraph;
```

**Notes:** Two overlaid `Area` series in a single `AreaChart` — both with `fill="none"` (line-only look, despite being `Area` components not `Line`), `strokeWidth={2}`. Colors: incoming `#3B82F6` (blue) / outgoing `#22C55E` (green). `YAxis` domain `[0, dataMax*1.1]`.

**Mock data** (`src/components/NetworkSpeedGraph/__mockData__/index.ts`):

