193	  /* Portfolio theme (dark) — from the dark-mode Figma frame */
194	  --portfolio-bg: var(--portfolio-bg-dark);
195	  --media-frame-shadow:
196	    0px 4px 7px 0px rgba(0, 0, 0, 0.85), 0px 1px 2px 0px rgba(0, 0, 0, 0.5),
197	    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
198	    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
