202	  --portfolio-ink: #fff9f2;
203	  /* #BBBBBB on this bg computes to 9.23:1 — the same value the old
204	       footnote-only token already used, since it worked well here. */
205	  --portfolio-muted: #bbbbbb;
206	  --portfolio-accent: #40c6b0;
207	
208	  --portfolio-category-design: #818cf8;
209	  --portfolio-category-design-hover: #a5b4fc;
210	  --portfolio-category-philosophy: #c084fc;
211	  --portfolio-category-philosophy-hover: #d8b4fe;
212	  --portfolio-category-craft: #fb923c;
213	  --portfolio-category-craft-hover: #fdba74;
214	  --portfolio-category-creativity: #eab308;
215	  --portfolio-category-creativity-hover: #facc15;
216	  --portfolio-category-culture: #2dd4bf;
217	  --portfolio-category-culture-hover: #5eead4;
218	  --portfolio-category-games: #4ade80;
219	  --portfolio-category-games-hover: #86efac;
