/* Tailwind v4 — imports all base, components, and utilities */
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

/* IBM Plex Mono — portfolio body/UI font, via @fontsource */
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/600.css";

/* IBM Plex Sans — portfolio long-form/label font (bio copy, section labels, footer).
   Variable weight (100–700) so any font-weight utility actually takes effect,
   not just the handful of static cuts the non-variable package would ship. */
@import "@fontsource-variable/ibm-plex-sans/wght.css";

/* ─── Font faces ──────────────────────────────────────────────────────────── */

/* Geist Sans — variable font, covers all weights from 100–900 */
@font-face {
  font-family: "Geist Sans";
  src: url("/node_modules/geist/dist/fonts/geist-sans/Geist-Variable.woff2")
    format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* Geist Mono — variable font, used only by the Undercurrent case-study
   sandbox (src/components/undercurrent-demo) for the secondary/technical
   text style the real design system uses (e.g. a DynamicBadge's monospace
   detail text). Declared globally alongside Geist Sans, same as every other
   font-face in this file, even though only one feature currently uses it. */
@font-face {
  font-family: "Geist Mono";
  src: url("/node_modules/geist/dist/fonts/geist-mono/GeistMono-Variable.woff2")
    format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* Redaction 35 — portfolio headline font, self-hosted in /public/fonts/.
   Regular and Italic are true cuts (not synthetic), so they share one family
   name and map onto CSS's own font-style axis — the `italic` utility class
   switches to the correct file automatically. */
@font-face {
  font-family: "Redaction 35";
  src: url("/fonts/Redaction_35-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Redaction 35";
  src: url("/fonts/Redaction_35-Italic.woff2") format("woff2");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* font-sans     → Geist Sans (body text and UI) */
  --font-sans: "Geist Sans", sans-serif;
  /* font-mono     → IBM Plex Mono (portfolio page body/UI text) */
  --font-mono: "IBM Plex Mono", monospace;
  /* font-redaction  → Redaction 35 (portfolio headline only) */
  --font-redaction: "Redaction 35", serif;
  /* font-plex-sans  → IBM Plex Sans Variable (portfolio long-form/label text) */
  --font-plex-sans: "IBM Plex Sans Variable", sans-serif;

  /* ─── Portfolio colors (codykeisler.me redesign) ─────────────────────────── */
  /* Use these as Tailwind utilities: bg-portfolio-bg, text-portfolio-ink, etc.
       Raw values live in :root / .dark below so theme switching is a variable
       swap — see the `dark` custom-variant above. */
  --color-portfolio-bg: var(--portfolio-bg);
  --color-portfolio-ink: var(--portfolio-ink);
  /* Single dim/secondary tone, used everywhere something needs to read as
       less prominent than portfolio-ink: section eyebrow labels, dates,
       taglines, footer copy, the nav breadcrumb badge, and footnotes. */
  --color-portfolio-muted: var(--portfolio-muted);
  --color-portfolio-accent: var(--portfolio-accent);

  /* Blog category tag colors — each a light/dark pair (see :root/.dark)
       plus a hover variant, replacing categoryConfig.ts's old raw Tailwind
       palette classes (which used the same shade in both themes and, per a
       contrast audit, failed WCAG AA in at least one theme for all 8). */
  --color-portfolio-category-design: var(--portfolio-category-design);
  --color-portfolio-category-design-hover: var(
    --portfolio-category-design-hover
  );
  --color-portfolio-category-philosophy: var(--portfolio-category-philosophy);
  --color-portfolio-category-philosophy-hover: var(
    --portfolio-category-philosophy-hover
  );
  --color-portfolio-category-craft: var(--portfolio-category-craft);
  --color-portfolio-category-craft-hover: var(--portfolio-category-craft-hover);
  --color-portfolio-category-creativity: var(--portfolio-category-creativity);
  --color-portfolio-category-creativity-hover: var(
    --portfolio-category-creativity-hover
  );
  --color-portfolio-category-culture: var(--portfolio-category-culture);
  --color-portfolio-category-culture-hover: var(
    --portfolio-category-culture-hover
  );
  --color-portfolio-category-games: var(--portfolio-category-games);
  --color-portfolio-category-games-hover: var(--portfolio-category-games-hover);
  --color-portfolio-category-art: var(--portfolio-category-art);
  --color-portfolio-category-art-hover: var(--portfolio-category-art-hover);
  --color-portfolio-category-outdoors: var(--portfolio-category-outdoors);
  --color-portfolio-category-outdoors-hover: var(
    --portfolio-category-outdoors-hover
  );

  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  /* Unconditional light/dark constants for --portfolio-bg — referenced by
       both the theme-conditional --portfolio-bg below and the theme-sweep
       probes in Footer.astro, so there's one source of truth for these two
       hex values regardless of which theme is currently active. */
  --portfolio-bg-light: #fff9f2;
  --portfolio-bg-dark: #18181b;

  /* Portfolio theme (light) — from the light-mode Figma frame */
  --portfolio-bg: var(--portfolio-bg-light);
  --portfolio-bg-gradient: none;
  --portfolio-ink: #18181b;
  /* Single dim/secondary tone (consolidated from the old muted/muted-2/
       footnote/nav-muted split — all four did the same job at slightly
       different, sometimes-contrast-failing shades). #6b6b6b on the light
       bg computes to 5.1:1, passing WCAG AA-normal (4.5:1) with margin. */
  --portfolio-muted: #6b6b6b;
  /* Deeper teal than the dark-mode accent — #40C6B0 only hits 2.02:1 on
       this light bg (fails badly); #0F7A6B computes to 5.0:1. */
  --portfolio-accent: #0f7a6b;

  /* Blog category tag colors — each shifted to a shade weight from the
       same hue family that clears 4.5:1 on this bg (the original single
       Tailwind palette shade, shared with dark mode, failed here). */
  --portfolio-category-design: #4338ca;
  --portfolio-category-design-hover: #3730a3;
  --portfolio-category-philosophy: #7e22ce;
  --portfolio-category-philosophy-hover: #6b21a8;
  --portfolio-category-craft: #c2410c;
  --portfolio-category-craft-hover: #9a3412;
  --portfolio-category-creativity: #854d0e;
  --portfolio-category-creativity-hover: #713f12;
  --portfolio-category-culture: #0f766e;
  --portfolio-category-culture-hover: #115e59;
  --portfolio-category-games: #15803d;
  --portfolio-category-games-hover: #166534;
  --portfolio-category-art: #a21caf;
  --portfolio-category-art-hover: #86198f;
  --portfolio-category-outdoors: #b45309;
  --portfolio-category-outdoors-hover: #92400e;

  --radius: 0.625rem;

  /* "Media frame" elevation — the shadow recipe every piece of inline
       case-study media shares (LoopVideo, LightboxImage, the Lightbox
       overlay, ProjectLayout's old embed box). Figma names this token
       "Light theme/Elevation" here and "Dark theme/Elevation" in .dark
       below — a flatter, single-tone drop shadow in light mode (no inset
       bevel; that only reads against a dark surface) vs. the dark theme's
       deeper shadow-plus-inner-highlight combination. */
  --media-frame-shadow:
    0px 3px 6px 0px rgba(0, 0, 0, 0.2), 0px 0px 0.5px 0px rgba(0, 0, 0, 0.15);

  /* Lightbox overlay backdrop — a warm near-white scrim in light mode so
       it reads against the light page behind it, vs. the dark theme's
       near-black scrim below. Unlike --media-frame-shadow above, this one
       genuinely needs to flip per theme (the old dark-only rgba(24,24,27,.7)
       looked wrong once the rest of the page went light). */
  --lightbox-backdrop: oklch(98.8% 0.00852 67.7deg / 70%);

  /* Case-study section stroke — a plain 1px outline (e.g. "The problem"
       in Ping). Figma's dark-mode value (#3c3c44) is a light-on-dark gray
       border; in light mode there's no equivalent Figma frame, so this is a
       low-opacity tint of --portfolio-ink instead, kept subtle enough to
       read as a hairline rather than a heavy outline. */
  --section-border-color: rgba(24, 24, 27, 0.15);
}

.dark {
  /* Portfolio theme (dark) — from the dark-mode Figma frame */
  --portfolio-bg: var(--portfolio-bg-dark);
  --media-frame-shadow:
    0px 4px 7px 0px rgba(0, 0, 0, 0.85), 0px 1px 2px 0px rgba(0, 0, 0, 0.5),
    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
  --lightbox-backdrop: rgba(24, 24, 27, 0.7);
  --section-border-color: #3c3c44;
  --portfolio-bg-gradient: linear-gradient(to bottom, #242429, #18181b);
  --portfolio-ink: #fff9f2;
  /* #BBBBBB on this bg computes to 9.23:1 — the same value the old
       footnote-only token already used, since it worked well here. */
  --portfolio-muted: #bbbbbb;
  --portfolio-accent: #40c6b0;

  --portfolio-category-design: #818cf8;
  --portfolio-category-design-hover: #a5b4fc;
  --portfolio-category-philosophy: #c084fc;
  --portfolio-category-philosophy-hover: #d8b4fe;
  --portfolio-category-craft: #fb923c;
  --portfolio-category-craft-hover: #fdba74;
  --portfolio-category-creativity: #eab308;
  --portfolio-category-creativity-hover: #facc15;
  --portfolio-category-culture: #2dd4bf;
  --portfolio-category-culture-hover: #5eead4;
  --portfolio-category-games: #4ade80;
  --portfolio-category-games-hover: #86efac;
  --portfolio-category-art: #e879f9;
  --portfolio-category-art-hover: #f0abfc;
  --portfolio-category-outdoors: #fbbf24;
  --portfolio-category-outdoors-hover: #fcd34d;
}

@layer base {
  html {
    @apply font-sans;
  }
  /* Gradient-aware portfolio background — bg-portfolio-bg only sets a flat
     background-color, but dark mode needs a background-image gradient too.
     `none` in light mode means only the flat color paints. */
  .bg-portfolio-page {
    background-color: var(--portfolio-bg);
    background-image: var(--portfolio-bg-gradient);
  }

  /* Shared headline treatment for every big Redaction-35 title on the site
     (home page's "Hi, I'm Cody", blog post titles, case-study titles).
     font-size is plain CSS, not a Tailwind arbitrary value — Tailwind v4's
     arbitrary-value parser can't handle the commas inside clamp(), even
     backslash-escaped, and silently drops the whole class instead of
     erroring. clamp() scales the size smoothly from 64px on small screens
     up to 80px, rather than snapping at a single breakpoint the way the
     home page's old text-[56px] sm:text-[80px] did — the 3vw term hits the
     64px floor around a 533px-wide viewport and the 80px ceiling around
     1067px, transitioning linearly in between. */
  .portfolio-headline {
    font-family: var(--font-redaction);
    font-size: clamp(4rem, 3rem + 3vw, 5rem);
    line-height: 0.94;
    letter-spacing: -2.4px;
    color: var(--portfolio-ink);
  }

  /* Inline `code` spans (MDX backtick syntax, e.g. blog posts and case
     studies referencing component/prop names like `Card`) — site-wide,
     not scoped to any one layout's prose wrapper, since both BlogLayout
     and ProjectLayout render MDX content that can contain inline code. */
  code {
    font-family: var(--font-mono);
    border-radius: 4px;
    padding: 4px;
    background-color: oklch(94.5% 0.044 73.9deg);
  }

  .dark code {
    background-color: oklch(33.5% 0.0104 286deg);
  }
}

/* Per-project icon/badge colors (index.astro, ProjectLayout.astro) come from
   MDX frontmatter and can optionally differ by theme — same --x-light/--x-dark
   -> --x resolution pattern as --portfolio-bg above, except these are set
   inline per-element (from content data) rather than globally in :root/.dark,
   so the resolution rule has to live here instead of alongside --portfolio-bg. */
[style*="--icon-color-light"] {
  --icon-color: var(--icon-color-light);
}
[style*="--badge-color-light"] {
  --badge-color: var(--badge-color-light);
}
.dark [style*="--icon-color-dark"] {
  --icon-color: var(--icon-color-dark);
}
.dark [style*="--badge-color-dark"] {
  --badge-color: var(--badge-color-dark);
}

@media (prefers-reduced-motion: no-preference) {
  [data-animate] {
    opacity: 0;
  }
}

/* Theme-toggle sweep, driven by the View Transitions API (see the click
   handler in Footer.astro). The browser snapshots the page before and after
   the .dark class toggles into ::view-transition-old(root) and
   ::view-transition-new(root); overriding the default cross-fade with a
   clip-path keyframe reveals the new-theme screenshot as an expanding line
   sweeping across, with the old screenshot sitting untouched underneath —
   so each side of the line is already showing its correct final theme. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

::view-transition-old(root) {
  z-index: 1;
}

::view-transition-new(root) {
  z-index: 2;
}

[data-theme-sweep-direction="light"]::view-transition-new(root) {
  animation: theme-sweep-up 500ms ease-in-out forwards;
}

[data-theme-sweep-direction="dark"]::view-transition-new(root) {
  animation: theme-sweep-down 500ms ease-in-out forwards;
}

@keyframes theme-sweep-up {
  from {
    clip-path: inset(100% 0 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@keyframes theme-sweep-down {
  from {
    clip-path: inset(0 0 100% 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

