/* ─── Network speed — received/sent in kbps, 30-min intervals ──────────── */
export const networkSpeedData: DataPoint[] = withTime(
  [
    [240, 480], [280, 520], [260, 500], [300, 560], [320, 580], [290, 540],
    [310, 560], [340, 600], [360, 620], [330, 580], [350, 600], [370, 640],
