export interface MeasureBarProps {
  /** Current fill percentage, 0-100. */
  percentage: number;
  /** Additional "projected" percentage shown as a hatched segment past the solid fill. */
  projectedPercentage?: number;
  warningThreshold?: number;
  criticalThreshold?: number;
}

export default function MeasureBar({
  percentage,
  projectedPercentage = 0,
  warningThreshold = 75,
  criticalThreshold = 90,
}: MeasureBarProps) {
  const value = Math.min(100, Math.max(0, percentage));
  const projected = Math.min(100 - value, Math.max(0, projectedPercentage));

  let fillColor = "var(--wt-demo-chart-ram-stroke)";
  if (value >= criticalThreshold) {
    fillColor = "var(--wt-demo-danger-bg-strong)";
  } else if (value >= warningThreshold) {
    fillColor = "var(--wt-demo-warning-text)";
  }

  return (
    <div
      className="relative h-10 w-full overflow-hidden rounded-[var(--wt-demo-radius-sm)] border"
      style={{ borderColor: "var(--wt-demo-neutral-border-weak)" }}
    >
      <div
        className="absolute top-0 left-0 h-full transition-[width]"
        style={{ width: `${value}%`, backgroundColor: fillColor }}
      />
      {projected > 0 && (
        <div
          className="absolute top-0 h-full"
          style={{
            left: `${value}%`,
            width: `${projected}%`,
            backgroundImage: `repeating-linear-gradient(45deg, transparent, transparent 4px, ${fillColor}80 4px, ${fillColor}80 5px)`,
          }}
        />
      )}
    </div>
  );
}

