input.old_string:
export interface ChartHoverOverlayProps extends CustomizedInjectedProps {
  activeIndex: number | null;
  data: DataPoint[];
  /** Which field's value positions the dot vertically, e.g. "memory", "cpu". */
  dataKey: string;
  /** Dot + line accent color. */
  color: string;
}

export function ChartHoverOverlay({
  activeIndex,
  data,
  dataKey,
  color,
  xAxisMap,
  yAxisMap,
  offset,
}: ChartHoverOverlayProps) {
  if (activeIndex == null || !xAxisMap || !yAxisMap || !offset) return null;

  const point = data[activeIndex];
  if (!point) return null;

  const xAxis = Object.values(xAxisMap)[0];
  const yAxis = Object.values(yAxisMap)[0];
  if (!xAxis || !yAxis) return null;

  const x = xAxis.scale(point.time);
  const y = yAxis.scale(point[dataKey]);
  const top = offset.top;
  const bottom = offset.top + offset.height;

  return (
    <g pointerEvents="none">
      <line
        x1={x}
        x2={x}
        y1={top}
        y2={bottom}
        stroke="var(--wt-demo-hover-line)"
        strokeDasharray="4 4"
        strokeWidth={1}
      />
      <circle
        cx={x}
        cy={y}
        r={4}
        fill={color}
        stroke="var(--wt-demo-hover-dot-stroke)"
        strokeWidth={2}
      />
    </g>
  );
}

