import {
  useActiveTooltipCoordinate,
  useIsTooltipActive,
  useOffset,
} from "recharts";

export interface ChartHoverOverlayProps {
  /** Dot marker color. Omit to render only the dashed line (e.g. dual-line charts with no single series to anchor to). */
  dotColor?: string;
}

/**
 * Renders inside a recharts chart (as a JSX child, not via the deprecated
 * <Customized> wrapper — recharts 3's chart-state hooks read live Redux
 * state directly, so this needs no props/state passed down from the card).
 * Draws a dashed vertical line spanning the plot area at the hovered
 * x-position, plus an optional dot marker at the hovered point.
 */
export function ChartHoverOverlay({ dotColor }: ChartHoverOverlayProps) {
  const isActive = useIsTooltipActive();
  const coordinate = useActiveTooltipCoordinate();
  const offset = useOffset();

  if (!isActive || !coordinate || !offset) return null;

  const top = offset.top ?? 0;
  const bottom = top + (offset.height ?? 0);

  return (
    <g pointerEvents="none">
      <line
        x1={coordinate.x}
        x2={coordinate.x}
        y1={top}
        y2={bottom}
        stroke="var(--wt-demo-hover-line)"
        strokeDasharray="4 4"
        strokeWidth={1}
      />
      {dotColor && (
        <circle
          cx={coordinate.x}
          cy={coordinate.y}
          r={4}
          fill={dotColor}
          stroke="var(--wt-demo-hover-dot-stroke)"
          strokeWidth={2}
        />
      )}
    </g>
  );
}

