import type { DataPoint } from "./types";

/* recharts' <Customized> extension point hands the render function real
 * plot-area pixel geometry (xAxisMap/yAxisMap/offset) computed from the
 * chart's own scales/margins, so the hover line + dot can be positioned in
 * the chart's actual coordinate space without recomputing those scales by
 * hand. Everything else about the hover payload recharts normally passes to
 * a <Customized> child is untyped in recharts' public types, so this reads
 * the fields it needs directly off the props object. */
interface CustomizedInjectedProps {
  xAxisMap?: Record<string, { scale: (value: number) => number }>;
  yAxisMap?: Record<string, { scale: (value: number) => number }>;
  offset?: { top: number; height: number };
}

export interface ChartHoverOverlayProps extends CustomizedInjectedProps {
  activeIndex: number | null;
  data: DataPoint[];
  /** Which field's value positions the dot vertically, e.g. "memory", "cpu". */
  dataKey: string;
  /** Dot + line accent color. */
  color: string;
  /** yAxisId to scale dataKey against, for dual-axis charts (e.g. Bandwidth's cumulative line). Defaults to the first axis. */
  yAxisId?: string;
  /** Render the dot marker. Set false for charts where no single series should anchor it (e.g. dual-line Network speed). */
  showDot?: boolean;
}

export function ChartHoverOverlay({
  activeIndex,
  data,
  dataKey,
  color,
  yAxisId,
  showDot = true,
  xAxisMap,
  yAxisMap,
  offset,
}: ChartHoverOverlayProps) {
  if (activeIndex == null || !xAxisMap || !yAxisMap || !offset) return null;

  const point = data[activeIndex];
  if (!point) return null;

  const xAxis = Object.values(xAxisMap)[0];
  const yAxis = yAxisId && yAxisMap[yAxisId] ? yAxisMap[yAxisId] : Object.values(yAxisMap)[0];
  if (!xAxis || !yAxis) return null;

  const x = xAxis.scale(point.time);
  const y = yAxis.scale(point[dataKey]);
  const top = offset.top;
  const bottom = offset.top + offset.height;

  return (
    <g pointerEvents="none">
      <line
        x1={x}
        x2={x}
        y1={top}
        y2={bottom}
        stroke="var(--wt-demo-hover-line)"
        strokeDasharray="4 4"
        strokeWidth={1}
      />
      {showDot && (
        <circle
          cx={x}
          cy={y}
          r={4}
          fill={color}
          stroke="var(--wt-demo-hover-dot-stroke)"
          strokeWidth={2}
        />
      )}
    </g>
  );
}

/** Pixel position of the bottom of the hover line, for anchoring a floating
 * date label below the chart — derived the same way ChartHoverOverlay
 * computes its line's x position, but from the raw onMouseMove chart
 * coordinates rather than recharts' <Customized> injected scales, since the
 * label lives outside the chart's SVG as a plain HTML element. */
export interface HoverLabelPosition {
  x: number;
  y: number;
}

