export interface HoverDateLabelProps {
  formatLabel: (time: number) => string;
}

/**
 * Floating date label anchored to the bottom of the hover line, e.g. "May 9,
 * 2026". Rendered as a <foreignObject> so the label itself can be normal
 * HTML/CSS (padding, rounded corners, font) while still using the chart's
 * own coordinate system for positioning — avoids duplicating scale math
 * outside the chart, unlike tracking raw mouse pixels via onMouseMove.
 */
export function HoverDateLabel({ formatLabel }: HoverDateLabelProps) {
  const isActive = useIsTooltipActive();
  const coordinate = useActiveTooltipCoordinate();
  const offset = useOffset();
  const label = useActiveTooltipLabel();

  if (!isActive || !coordinate || !offset || label == null) return null;

  const bottom = (offset.top ?? 0) + (offset.height ?? 0);
  const labelWidth = 96;

  return (
    <foreignObject
      x={coordinate.x - labelWidth / 2}
      y={bottom + 2}
      width={labelWidth}
      height={20}
      style={{ overflow: "visible", pointerEvents: "none" }}
    >
      <div
        className="mx-auto w-fit rounded-[var(--wt-demo-radius-xs)] px-1.5 py-0.5 font-mono text-xs whitespace-nowrap"
        style={{
          backgroundColor: "var(--wt-demo-hover-label-bg)",
          color: "var(--wt-demo-hover-label-text)",
        }}
      >
        {formatLabel(Number(label))}
      </div>
    </foreignObject>
  );
}

