              domain={["dataMin", "dataMax"]}
            />
            <YAxis
              yAxisId="bars"
              hide
              domain={[0, (dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.05)]}
            />
            <YAxis
              yAxisId="cumulative"
              orientation="right"
              hide
              domain={[0, (dataMax: number) => (dataMax === 0 ? 1 : dataMax * 1.1)]}
            />
            <Bar
              yAxisId="bars"
              dataKey="incoming"
              fill="var(--wt-demo-chart-bandwidth-incoming)"
              animationDuration={400}
              stackId="a"
              shape={<TopBar />}
            />
            <Bar
              yAxisId="bars"
              dataKey="outgoing"
              fill="var(--wt-demo-chart-bandwidth-outgoing)"
              animationDuration={400}
              stackId="a"
              shape={<BottomBar />}
            />
            <Line
              yAxisId="cumulative"
              dot={false}
              dataKey="totalCumulative"
              type="monotone"
              stroke="var(--wt-demo-chart-bandwidth-cumulative)"
              strokeWidth={2}
              animationDuration={400}
            />
            <Customized
              component={(props: object) => (
                <ChartHoverOverlay
                  {...props}
                  activeIndex={activeIndex}
                  data={chartData}
                  dataKey="totalCumulative"
