export interface MeasureBarProps {
  /** Current fill percentage, 0-100. */
  percentage: number;
  /** Additional "projected" percentage shown as a hatched segment past the solid fill. */
  projectedPercentage?: number;
  warningThreshold?: number;
  criticalThreshold?: number;
}

export default function MeasureBar({
  percentage,
  projectedPercentage = 0,
  warningThreshold = 75,
  criticalThreshold = 90,
}: MeasureBarProps) {
  const value = Math.min(100, Math.max(0, percentage));
  const projected = Math.min(100 - value, Math.max(0, projectedPercentage));

  const isCritical = value >= criticalThreshold;
  const isWarning = value >= warningThreshold;

  return (
    <div
      className="relative flex h-10 w-full overflow-hidden rounded-[var(--wt-demo-radius-sm)] border"
      style={{ borderColor: "var(--wt-demo-neutral-border-weak)" }}
    >
      {/* Used space — light fill segment */}
      <div
        style={{
          width: `${value}%`,
          backgroundColor: isCritical
            ? "#bfdbfe"
            : isWarning
              ? "#fde68a"
              : "#bfdbfe",
        }}
      />
      {/* Projected growth — a darker segment bordered on its trailing edge */}
      {projected > 0 && (
        <div
          className="border-r-2"
          style={{
            width: `${projected}%`,
            backgroundColor: isCritical ? "var(--wt-demo-danger-bg-strong)" : "#3b82f6",
            borderColor: "var(--wt-demo-neutral-text-main)",
          }}
        />
      )}
    </div>
  );
}

