import { Info } from "lucide-react";
import type { ReactNode } from "react";

export interface WtCardProps {
  title: string;
  /** Tooltip message for the (i) info icon in the header. Omit to hide the icon. */
  infoMessage?: string;
  children: ReactNode;
  /** Optional footer row, e.g. Disk space's red "Full by" bar. */
  footer?: ReactNode;
  /** Background color override for the footer (danger red when disk is critical). */
  footerBgColor?: string;
  /** Brighter accent line color along the footer's top edge, giving it a
   * layered/raised look on top of the card body rather than a flat block. */
  footerAccentColor?: string;
}

export default function WtCard({
  title,
  infoMessage,
  children,
  footer,
  footerBgColor,
  footerAccentColor,
}: WtCardProps) {
  return (
    <div
      className="flex h-full flex-col overflow-hidden rounded-[var(--wt-demo-radius-md)] border"
      style={{
        backgroundColor: "var(--wt-demo-neutral-bg-main)",
        borderColor: "var(--wt-demo-neutral-border-weak)",
      }}
    >
      <div className="flex items-center justify-between px-[var(--wt-demo-space-200)] pt-[var(--wt-demo-space-200)]">
        <span
          className="text-sm font-medium"
          style={{ color: "var(--wt-demo-neutral-text-main)" }}
        >
          {title}
        </span>
        {infoMessage && (
          <span title={infoMessage} aria-label={infoMessage}>
            <Info
              size={16}
              className="shrink-0"
              style={{ color: "var(--wt-demo-neutral-text-weak)" }}
            />
          </span>
        )}
      </div>

      <div className="flex flex-1 flex-col overflow-hidden">{children}</div>

      {footer && (
        <div
          className="relative px-[var(--wt-demo-space-200)] py-[var(--wt-demo-space-150)]"
          style={{
            backgroundColor: footerBgColor,
            boxShadow: footerAccentColor
              ? `inset 0 1px 0 0 ${footerAccentColor}`
              : undefined,
          }}
        >
          {footer}
        </div>
      )}
    </div>
  );
}

