import { Info } from "lucide-react";
import { Tooltip } from "@base-ui/react/tooltip";

export interface WtInfoTooltipProps {
  message: string;
}

/**
 * The (i) info icon in a card header. Uses Base UI's Tooltip (not the
 * native `title` attribute) so the open delay is controllable — browsers
 * apply their own fixed ~1-1.5s delay to `title`, which reads as sluggish.
 */
export default function WtInfoTooltip({ message }: WtInfoTooltipProps) {
  return (
    <Tooltip.Provider delay={500}>
      <Tooltip.Root>
        <Tooltip.Trigger
          aria-label={message}
          className="flex shrink-0 cursor-default items-center justify-center"
        >
          <Info size={16} style={{ color: "var(--wt-demo-neutral-text-weak)" }} />
        </Tooltip.Trigger>
        <Tooltip.Portal>
          <Tooltip.Positioner sideOffset={6}>
            <Tooltip.Popup
              className="rounded-[var(--wt-demo-radius-xs)] px-2 py-1 font-mono text-xs"
              style={{
                backgroundColor: "var(--wt-demo-hover-label-bg)",
                color: "var(--wt-demo-hover-label-text)",
                maxWidth: "220px",
              }}
            >
              {message}
            </Tooltip.Popup>
          </Tooltip.Positioner>
        </Tooltip.Portal>
      </Tooltip.Root>
    </Tooltip.Provider>
  );
}

