/**
 * Point-to-previous-point percentage change for `key` at `index`.
 * Returns undefined when there's no earlier point to compare against (index
 * 0 of the full series) or when either value is missing. Returns 'new' when
 * the previous point was a genuine zero and the current point is positive,
 * rather than hiding the spike as "unknown".
 */
export function computeChange(
  data: DataPoint[],
  key: string,
  index: number,
): ChangeResult {
  if (index < 1) return undefined;
  const current = data[index][key];
  const previous = data[index - 1][key];
  if (current == null || previous == null) return undefined;
  if (previous === 0) return current > 0 ? "new" : undefined;
  return Math.round(((current - previous) / previous) * 100);
}

/**
 * Same as computeChange, but for a card that only displays a slice of a
 * larger series (e.g. graphData = fullData.slice(midpoint) for period
 * comparison) — takes the full unsliced series and an index into it, so
 * hovering the visible window's first point can still diff against the
 * previous period's last point instead of going blank (which otherwise
 * causes a jarring layout shift as StatHighlight's trend row disappears
 * and reappears while scrubbing across that boundary).
 */
export function computeChangeInSeries(
  fullData: DataPoint[],
  key: string,
  absoluteIndex: number,
): ChangeResult {
  return computeChange(fullData, key, absoluteIndex);
}

