1	import type { ChangeResult, DataPoint } from "./types";
2	
3	/** Mean of `key` across data points that have a value; skips null/missing readings. */
4	export function avg(data: DataPoint[], key: string): number {
5	  const present = data.filter((point) => point[key] != null);
6	  if (!present.length) return 0;
7	  return present.reduce((sum, point) => sum + point[key], 0) / present.length;
8	}
9	
10	/**
11	 * Point-to-previous-point percentage change for `key` at `index`.
12	 * Returns undefined when there's no earlier point to compare against (index
13	 * 0 of the full series) or when either value is missing. Returns 'new' when
14	 * the previous point was a genuine zero and the current point is positive,
15	 * rather than hiding the spike as "unknown".
16	 */
17	export function computeChange(
18	  data: DataPoint[],
19	  key: string,
20	  index: number,
21	): ChangeResult {
22	  if (index < 1) return undefined;
23	  const current = data[index][key];
24	  const previous = data[index - 1][key];
25	  if (current == null || previous == null) return undefined;
26	  if (previous === 0) return current > 0 ? "new" : undefined;
27	  return Math.round(((current - previous) / previous) * 100);
28	}
29	
30	
31	/**
32	 * Period-over-period percentage change between a current and previous average.
33	 * See ChangeResult for the 'new'-baseline sentinel.
34	 */
35	export function periodChange(currentAvg: number, prevAvg: number): ChangeResult {
36	  if (prevAvg === 0) return currentAvg > 0 ? "new" : undefined;
37	  return Math.round(((currentAvg - prevAvg) / prevAvg) * 100);
38	}
39	
40	/**
41	 * Resolves a change result to a CSS color var. `direction` controls whether
42	 * an increase reads as concerning (server load, disk usage) or unremarkable
43	 * (network throughput, where "incoming +20%" isn't inherently bad) — Wallaby's
44	 * server-health-only "increase is always danger" rule doesn't hold for every
45	 * card in this dashboard.
46	 */
47	export function changeColorForIncrease(
48	  changePercent: ChangeResult,
49	  direction: "increase-is-bad" | "increase-is-good",
50	): string | undefined {
51	  if (changePercent === undefined) return undefined;
52	  const isIncrease = changePercent === "new" || changePercent > 0;
53	  const isDecrease = typeof changePercent === "number" && changePercent < 0;
54	  if (!isIncrease && !isDecrease) return undefined;
55	  const goodColor = "var(--wt-demo-success-text)";
