            />
            <Area
              dot={false}
              dataKey="sent"
              type="monotone"
              stroke="var(--wt-demo-chart-network-outgoing)"
              fill="var(--wt-demo-chart-network-outgoing-fill)"
              fillOpacity={0.5}
              strokeWidth={2}
              animationDuration={400}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </WtCard>
  );
}

