  );

  --wt-demo-chart-cpu-stroke: #c17f0a;
  --wt-demo-chart-cpu-fill: #faf0dc;
  --wt-demo-chart-ram-stroke: #3d5ec2;
  --wt-demo-chart-ram-fill: #e6ecfb;
  --wt-demo-chart-bandwidth-incoming: #4c6ef5;
  --wt-demo-chart-bandwidth-outgoing: #a9bbfa;
  --wt-demo-chart-bandwidth-cumulative: #e64980;
  --wt-demo-chart-network-incoming: #4c6ef5;
  --wt-demo-chart-network-incoming-fill: #eef2fd;
  --wt-demo-chart-network-outgoing: #2f9e5c;
  --wt-demo-chart-network-outgoing-fill: #e8f7ee;

  --wt-demo-hover-line: #b0b0b5;
  --wt-demo-hover-dot-stroke: var(--wt-demo-neutral-bg-main);
  --wt-demo-hover-label-bg: #f1f1f2;
  --wt-demo-hover-label-text: #46464a;
}

