import type { DataPoint } from "./types";

/* All series share a common time axis (30-minute intervals, ~1 day of
 * history split into a "previous" half and a "current" half so idle-state
 * cards can show period-over-period change) so hovering conceptually lines
 * up across cards, even though each card manages its own hover state. */
const INTERVAL_SECONDS = 1800;
const POINTS_PER_PERIOD = 24;
const BASE_TIME =
  Math.floor(Date.UTC(2026, 4, 9, 0, 0, 0) / 1000) -
  INTERVAL_SECONDS * POINTS_PER_PERIOD;

function withTime<T extends Record<string, number>>(values: T[]): DataPoint[] {
  return values.map((value, i) => ({
    time: BASE_TIME + INTERVAL_SECONDS * i,
    ...value,
  }));
}

/* ─── CPU Utilization — % used, previous period (idx 0-23) + current (24-47) ── */
export const cpuData: DataPoint[] = withTime(
  [
    58, 60, 63, 61, 59, 62, 65, 68, 70, 66, 63, 61, 59, 62, 64, 67, 69, 65, 62,
    60, 63, 66, 68, 64,
    // current period
    62, 65, 68, 71, 73, 70, 67, 64, 66, 69, 72, 75, 73, 70, 68, 65, 63, 66, 69,
    72, 74, 71, 68, 75,
  ].map((cpu) => ({ cpu })),
);

/* ─── RAM usage — bytes used out of 16 GB total ────────────────────────── */
const GB = 1024 * 1024 * 1024;
export const ramData: DataPoint[] = withTime(
  [
    12.6, 12.8, 13.1, 12.9, 12.7, 13.0, 13.3, 13.6, 13.8, 13.4, 13.1, 12.9,
    12.7, 13.0, 13.2, 13.5, 13.7, 13.3, 13.0, 12.8, 13.1, 13.4, 13.6, 13.2,
    // current period
    13.0, 13.3, 13.6, 13.9, 14.1, 13.8, 13.5, 13.2, 13.4, 13.7, 14.0, 14.3,
    14.1, 13.8, 13.6, 13.3, 13.1, 13.4, 13.7, 14.0, 14.2, 13.9, 13.6, 14.2,
  ].map((gb) => ({ memory: gb * GB })),
);
export const RAM_TOTAL_BYTES = 16 * GB;

/* ─── Disk space — static snapshot, no chart. Values live directly on the card. */
export const diskSpace = {
  usedGB: 186,
  totalGB: 200,
  percentUsed: 93,
  growthGBPerDay: 1.5,
  projectedFullDate: "Jun 26, 2026",
  projectedDaysLeft: 9,
};

/* ─── Bandwidth — incoming/outgoing MB per day. Its own daily time axis
 * (rather than the shared 30-min one above) since a monthly bar chart needs
 * one point per calendar day, not per half-hour — 31 "previous month" days
 * followed by 31 "current month" days so the idle-state period comparison
 * still works, and the chart itself shows a full 31-day month. */
const BANDWIDTH_INTERVAL_SECONDS = 86400;
const BANDWIDTH_BASE_TIME =
  Math.floor(Date.UTC(2026, 4, 9, 0, 0, 0) / 1000) - BANDWIDTH_INTERVAL_SECONDS * 31;

export const bandwidthData: DataPoint[] = [
  // Previous month — 31 days, moderate baseline traffic
  [4.8, 9.2], [5.6, 10.8], [5.3, 10.1], [5.9, 11.3], [6.4, 12.4], [4.1, 7.8],
  [3.9, 7.2], [5.1, 9.6], [5.8, 11.1], [5.5, 10.5], [4.7, 9.0], [5.2, 10.0],
  [4.3, 8.2], [4.0, 7.6], [5.1, 9.9], [5.6, 10.8], [5.3, 10.2], [5.9, 11.3],
  [6.1, 11.7], [4.6, 8.9], [4.4, 8.3], [5.7, 11.0], [6.1, 11.7], [5.8, 11.1],
  [4.9, 9.4], [4.6, 8.8], [5.4, 10.4], [5.9, 11.4], [5.6, 10.7], [6.2, 11.9],
  [5.0, 9.6],
  // Current month — 31 days, ramping up through the month
  [4.6, 8.8], [5.1, 9.6], [4.8, 9.1], [5.4, 10.4], [5.9, 11.4], [7.5, 14.6],
  [6.2, 12.0], [4.5, 8.6], [4.2, 8.0], [5.6, 10.8], [6.1, 11.7], [5.8, 11.1],
  [8.1, 15.0], [6.6, 12.6], [4.8, 9.2], [4.6, 8.9], [5.9, 11.4], [6.4, 12.3],
  [6.1, 11.7], [8.5, 15.8], [6.8, 12.9], [5.0, 9.6], [4.8, 9.2], [6.2, 11.9],
  [6.7, 12.8], [6.4, 12.3], [8.9, 16.4], [7.1, 13.5], [5.3, 10.2], [5.1, 9.8],
  [6.5, 12.5],
].map(([incoming, outgoing], i) => ({
  time: BANDWIDTH_BASE_TIME + BANDWIDTH_INTERVAL_SECONDS * i,
  incoming,
  outgoing,
}));

/* ─── Network speed — received/sent in kbps, 30-min intervals ──────────── */
export const networkSpeedData: DataPoint[] = withTime(
  [
    [240, 480], [280, 520], [260, 500], [300, 560], [320, 580], [290, 540],
    [310, 560], [340, 600], [360, 620], [330, 580], [350, 600], [370, 640],
    [300, 560], [310, 580], [330, 600], [320, 580], [340, 600], [360, 620],
    [350, 610], [380, 640], [370, 630], [360, 620], [350, 610], [300, 580],
    // current period
    [300, 580], [320, 600], [340, 620], [360, 640], [370, 650], [380, 660],
    [360, 640], [370, 650], [360, 640], [350, 630], [360, 640], [370, 650],
    [300, 590], [290, 580], [310, 600], [320, 610], [330, 620], [340, 630],
    [350, 640], [360, 650], [370, 660], [380, 670], [300, 600], [310, 580],
  ].map(([received, sent]) => ({ received, sent })),
);

