  [
    ...generateNetworkSpeedWindow(300, 560, 10, 3),
    // current period — same diurnal shape, slightly higher baseline
    ...generateNetworkSpeedWindow(320, 590, 10, 17),
  ].map(([received, sent]) => ({ received, sent })),
);

