      lang: "tsx",
      theme: themeName,
    });
    return tokens.map((line) =>
      line.map((token) => ({
        text: token.content,
        color: token.color ?? "",
        italic: (token.fontStyle ?? 0) === 1,
      })),
    );
  };

  cachedTokens = {
    dark: toLines("linear-dark"),
    light: toLines("linear-light"),
  };
  return cachedTokens;
}

