  --wt-editor-text-muted: #595c64;
  --wt-editor-line-number: #4f5259;
  --wt-editor-line-number-active: #c1c3c8;
  --wt-editor-wrap-guide: #2e2f33;
  --wt-editor-wrap-guide-active: #3c3e44;
  --wt-editor-cursor: #c9d5ff;
  --wt-editor-breadcrumb-text: #595c64;
}

.dark .wt-editor,
.wt-editor.dark {
  /* Explicit restatement of dark values — see watchtower-demo.css for why
     this exists: dark values ARE the defaults here, this just gives light
     mode below something concrete to override. */
  --wt-editor-bg: #1f2023;
  --wt-editor-gutter-bg: #1f2023;
  --wt-editor-border: #3c3e44;
  --wt-editor-text-main: #c1c3c8;
  --wt-editor-text-muted: #595c64;
  --wt-editor-line-number: #4f5259;
  --wt-editor-line-number-active: #c1c3c8;
  --wt-editor-wrap-guide: #2e2f33;
  --wt-editor-wrap-guide-active: #3c3e44;
