import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import "@/styles/watchtower-demo-editor.css";
import {
  CODE_SNIPPET,
  FILE_PATH,
  getTokenizedLines,
  type TokenizedLine,
} from "./typingCodeSnippet";
import { useTypewriter } from "./useTypewriter";

const INDENT_SIZE = 2;

function countLeadingIndent(line: string): number {
  const match = /^ */.exec(line);
  const spaces = match ? match[0].length : 0;
  return Math.floor(spaces / INDENT_SIZE);
}

const SNIPPET_LINES = CODE_SNIPPET.replace(/\n$/, "").split("\n");
const LINE_INDENTS = SNIPPET_LINES.map(countLeadingIndent);
const FULL_TEXT_LENGTH = CODE_SNIPPET.length;

/**
 * Slices a tokenized line's tokens down to `revealCount` characters total,
 * dropping/truncating tokens past that point. Returns the trimmed tokens
 * plus how many characters were consumed, so the caller can carry the
 * remainder into the next line.
 */
function revealLine(
  tokens: TokenizedLine,
  revealBudget: number,
): { tokens: TokenizedLine; consumed: number } {
  const result: TokenizedLine = [];
  let consumed = 0;
  for (const token of tokens) {
    if (consumed >= revealBudget) break;
    const remaining = revealBudget - consumed;
    if (token.text.length <= remaining) {
      result.push(token);
      consumed += token.text.length;
    } else {
      result.push({ ...token, text: token.text.slice(0, remaining) });
      consumed += remaining;
    }
  }
  return { tokens: result, consumed };
}

export default function TypingCodeEditor() {
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const [tokenLines, setTokenLines] = useState<{
    dark: TokenizedLine[];
    light: TokenizedLine[];
  } | null>(null);

  useEffect(() => {
    let cancelled = false;
    getTokenizedLines().then((lines) => {
      if (!cancelled) setTokenLines(lines);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const { revealedCount, hasStartedTyping, isDone } = useTypewriter(
    rootRef,
    CODE_SNIPPET,
  );

  // \n characters count toward revealedCount (they're part of CODE_SNIPPET)
  // but consume their own budget unit without rendering a token — this
  // walks lines in lockstep with that count, one \n per line boundary.
  let remainingBudget = revealedCount;
  const visibleLineCount = tokenLines
    ? (() => {
        let count = 0;
        for (const line of tokenLines.dark) {
          if (remainingBudget <= 0) break;
          const lineTextLength =
            line.reduce((sum, t) => sum + t.text.length, 0) + 1; // +1 for \n
          count += 1;
          remainingBudget -= lineTextLength;
        }
        return count;
      })()
    : 0;

  return (
    <div ref={rootRef} className="wt-editor mt-10">
      <p
        className="mb-2 text-xs"
        style={{ color: "var(--wt-editor-breadcrumb-text)" }}
      >
        Watchtower3/Code
      </p>

      <div
        className="overflow-hidden rounded-xl border"
        style={{
          backgroundColor: "var(--wt-editor-bg)",
          borderColor: "var(--wt-editor-border)",
        }}
      >
        <div
          className="border-b px-5 py-3 text-sm italic"
          style={{
            borderColor: "var(--wt-editor-border)",
            color: "var(--wt-editor-text-muted)",
          }}
        >
          {FILE_PATH}
        </div>

        <div className="h-[340px] overflow-hidden px-5 py-4">
          {hasStartedTyping && tokenLines && (
            <CodeBody
              tokenLines={shouldReduceMotion ? tokenLines.dark : tokenLines.dark}
              visibleLineCount={visibleLineCount}
              revealedCount={revealedCount}
              isDone={isDone}
            />
          )}
        </div>
      </div>
    </div>
  );
}

function CodeBody({
  tokenLines,
  visibleLineCount,
  revealedCount,
  isDone,
}: {
  tokenLines: TokenizedLine[];
  visibleLineCount: number;
  revealedCount: number;
  isDone: boolean;
}) {
  let budgetLeft = revealedCount;

  return (
    <div className="font-mono text-[13px] leading-6">
      {tokenLines.slice(0, visibleLineCount + 1).map((tokens, i) => {
        if (i >= visibleLineCount) {
          // Partially-revealed current line.
          const { tokens: visibleTokens } = revealLine(tokens, budgetLeft);
          return (
            <CodeLine
              key={i}
              lineNumber={i + 1}
              indent={LINE_INDENTS[i] ?? 0}
              tokens={visibleTokens}
              showCursor={!isDone}
            />
          );
        }

        const lineTextLength =
          tokens.reduce((sum, t) => sum + t.text.length, 0) + 1;
        budgetLeft -= lineTextLength;
        return (
          <CodeLine
            key={i}
            lineNumber={i + 1}
            indent={LINE_INDENTS[i] ?? 0}
            tokens={tokens}
            showCursor={false}
          />
        );
      })}
    </div>
  );
}

function CodeLine({
  lineNumber,
  indent,
  tokens,
  showCursor,
}: {
  lineNumber: number;
  indent: number;
  tokens: TokenizedLine;
  showCursor: boolean;
}) {
  return (
    <div className="flex">
      <span
        className="w-8 shrink-0 text-right select-none"
