          <span
            key={guideIndex}
            aria-hidden="true"
            className="absolute top-0 bottom-0 w-px"
            style={{
              left: `${16 + guideIndex * 16}px`,
              backgroundColor: "var(--wt-editor-wrap-guide)",
            }}
