  const content = fs.readFileSync('src/components/watchtower-demo/typingCodeSnippet.ts', 'utf8');
  const match = content.match(/export const CODE_SNIPPET = \`([\s\S]*?)\`;/);
  const CODE_SNIPPET = match[1];

  const INDENT_SIZE = 2;
  function countLeadingIndent(line) {
    const m = /^ */.exec(line);
    const spaces = m ? m[0].length : 0;
    return Math.floor(spaces / INDENT_SIZE);
  }
  const SNIPPET_LINES = CODE_SNIPPET.replace(/\n\$/, '').split('\n');
  const LINE_INDENTS = SNIPPET_LINES.map(countLeadingIndent);

  function stripLeadingWhitespace(tokens, count) {
    if (count <= 0 || tokens.length === 0) return tokens;
    const [first, ...rest] = tokens;
    const stripped = first.text.slice(count);
    return stripped ? [{ ...first, text: stripped }, ...rest] : rest;
  }

  const { codeToTokens } = shiki;
  const result = await codeToTokens(CODE_SNIPPET, {
    lang: 'tsx',
    theme: { name: 'test', type: 'dark', fg: '#fff', bg: '#000', settings: [] },
  });
  const tokenLines = result.tokens.map(line => line.map(t => ({ text: t.content, color: t.color ?? '', italic: false })));

  function computeVisibleLines(tokenLines, revealedCount) {
    const result = [];
    let budget = revealedCount;
    for (let i = 0; i < tokenLines.length; i++) {
      if (budget <= 0) break;
      const line = tokenLines[i];
      const lineLength = line.reduce((sum, t) => sum + t.text.length, 0);
      const lineWithNewlineLength = lineLength + 1;
      const indentChars = (LINE_INDENTS[i] ?? 0) * INDENT_SIZE;
      if (budget >= lineWithNewlineLength) {
        result.push({ lineNumber: i+1, indent: LINE_INDENTS[i] ?? 0, tokens: stripLeadingWhitespace(line, indentChars), isCurrentLine: false });
        budget -= lineWithNewlineLength;
      } else {
        const trimmed = [];
        let consumed = 0;
        for (const token of line) {
          if (consumed >= budget) break;
          const remaining = budget - consumed;
          if (token.text.length <= remaining) { trimmed.push(token); consumed += token.text.length; }
          else { trimmed.push({ ...token, text: token.text.slice(0, remaining) }); consumed += remaining; }
        }
        const strippableIndent = Math.min(indentChars, consumed);
        result.push({ lineNumber: i+1, indent: LINE_INDENTS[i] ?? 0, tokens: stripLeadingWhitespace(trimmed, strippableIndent), isCurrentLine: true });
        budget = 0;
      }
    }
    return result;
