  const visible = computeVisibleLines(tokenLines, upToLine14);
  for (const line of visible.slice(7, 14)) {
    console.log(line.lineNumber, 'indent=' + line.indent, JSON.stringify(line.tokens.map(t=>t.text).join('')));
  }
