                lineNumber={line.lineNumber}
                indent={line.indent}
                tokens={line.tokens}
                showCursor={line.isCurrentLine && !isDone}
                reduceMotion={Boolean(shouldReduceMotion)}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

