const fs = require('fs');
const content = fs.readFileSync('src/components/watchtower-demo/typingCodeSnippet.ts', 'utf8');
const match = content.match(/export const CODE_SNIPPET = \`([\s\S]*?)\`;/);
const code = match[1];

function findBurstRanges(code) {
  const ranges = [];
  const selfClosingPattern = /\s*\/>/g;
  for (const m of code.matchAll(selfClosingPattern)) ranges.push({ start: m.index, end: m.index + m[0].length, kind: 'self-close' });
  const closingTagPattern = /<\/[A-Za-z][A-Za-z0-9.]*>/g;
  for (const m of code.matchAll(closingTagPattern)) ranges.push({ start: m.index, end: m.index + m[0].length, kind: 'close-tag' });
  const doubleBraceClosePattern = / \}\}/g;
  for (const m of code.matchAll(doubleBraceClosePattern)) ranges.push({ start: m.index, end: m.index + m[0].length, kind: 'brace-close' });
  return ranges.sort((a,b) => a.start - b.start);
}

const ranges = findBurstRanges(code);
for (const r of ranges) {
  console.log(r.kind, JSON.stringify(code.slice(r.start, r.end)));
}
console.log('total bursts:', ranges.length);
"

