1	export interface BurstRange {
2	  /** Character offset (into CODE_SNIPPET) where the burst starts. */
3	  start: number;
4	  /** Character offset where the burst ends (exclusive). */
5	  end: number;
6	}
7	
8	/**
9	 * Scans `code` for editor-autocomplete-style closer patterns — a
10	 * self-closing tag's trailing "/>", a closing tag like "</Box>", and a
11	 * brace pair's closer immediately following its opener with nothing but
12	 * whitespace/other closers in between (e.g. "}}" right after "{{...}}"'s
13	 * content ends) — and returns the character ranges that should reveal as
14	 * one instant jump rather than character-by-character, mimicking an editor
15	 * auto-inserting the matching closer the moment you type the opener.
16	 *
17	 * Deliberately conservative: only exact closing-tag/brace-pair patterns are
18	 * detected, not general "autocomplete a whole identifier" behavior — false
19	 * positives here would visibly skip real typed content.
20	 */
21	/** Common short prefix an editor would realistically still hand-type before
22	 * a suggestion is confident enough to accept — e.g. typing "lab" then
23	 * accepting "el" to complete "label". Kept small (1-2 chars) so the burst
24	 * still reads as "mostly autocompleted," not "appeared from nothing." */
25	const MANUAL_PREFIX_CHARS = 2;
26	
27	export function findBurstRanges(code: string): BurstRange[] {
28	  const ranges: BurstRange[] = [];
29	
30	  // Self-closing tags: "/>" right after the tag's own attributes, e.g.
31	  // `<StatHighlight label="Total" value={totalLabel} />` — burst just the
32	  // final " />" (or "/>"), not the whole tag.
33	  const selfClosingPattern = /\s*\/>/g;
34	  for (const match of code.matchAll(selfClosingPattern)) {
35	    ranges.push({ start: match.index, end: match.index + match[0].length });
36	  }
37	
38	  // Closing tags: "</Name>" — burst the whole closer as one unit.
39	  const closingTagPattern = /<\/[A-Za-z][A-Za-z0-9.]*>/g;
40	  for (const match of code.matchAll(closingTagPattern)) {
41	    ranges.push({ start: match.index, end: match.index + match[0].length });
42	  }
43	
44	  // Matched double-brace pairs opened by "={{ " — burst the closing "}}"
45	  // once its matching opener has been typed (e.g. sx={{ display: "flex" }}
46	  // bursts in the trailing " }}").
47	  const doubleBraceClosePattern = / \}\}/g;
48	  for (const match of code.matchAll(doubleBraceClosePattern)) {
49	    ranges.push({ start: match.index, end: match.index + match[0].length });
50	  }
51	
52	  // JSX attribute names — "label=", "value=", "unit=", "sx=", etc. — the
53	  // few leading chars are hand-typed, then the rest of the identifier
54	  // (plus the "=") bursts in as an accepted suggestion. Matches a bare
55	  // identifier immediately followed by "=" (not "=="), only where it reads
56	  // as an attribute (preceded by whitespace, i.e. inside a tag).
57	  const attrNamePattern = /(?<=[\s<])([A-Za-z][A-Za-z0-9]*)=(?!=)/g;
58	  for (const match of code.matchAll(attrNamePattern)) {
59	    const name = match[1];
60	    if (name.length > MANUAL_PREFIX_CHARS) {
61	      const nameStart = match.index;
62	      ranges.push({
63	        start: nameStart + MANUAL_PREFIX_CHARS,
64	        end: nameStart + name.length + 1, // +1 for the "="
65	      });
66	    }
67	  }
68	
69	  // Property-access identifiers — ".value", ".unit", etc. — same
70	  // hand-type-a-prefix-then-accept pattern as attribute names.
71	  const propertyAccessPattern = /\.([A-Za-z][A-Za-z0-9]*)/g;
72	  for (const match of code.matchAll(propertyAccessPattern)) {
73	    const name = match[1];
74	    if (name.length > MANUAL_PREFIX_CHARS) {
75	      const nameStart = match.index + 1; // skip the "."
76	      ranges.push({
77	        start: nameStart + MANUAL_PREFIX_CHARS,
78	        end: nameStart + name.length,
79	      });
80	    }
81	  }
82	
83	  return mergeOverlapping(ranges.sort((a, b) => a.start - b.start));
84	}
85	
86	function mergeOverlapping(ranges: BurstRange[]): BurstRange[] {
87	  const merged: BurstRange[] = [];
88	  for (const range of ranges) {
89	    const last = merged.at(-1);
90	    if (last && range.start <= last.end) {
91	      last.end = Math.max(last.end, range.end);
92	    } else {
93	      merged.push({ ...range });
94	    }
95	  }
96	  return merged;
97	}
98	
99	/**
100	 * Given the reveal cursor sitting at `fromIndex`, returns the burst range
101	 * whose start exactly equals `fromIndex`, if any — the caller advances
102	 * straight to `range.end` in one step instead of one character at a time.
103	 */
104	export function findBurstAt(
105	  ranges: BurstRange[],
