  --wt-editor-text-main: #282a30;
  --wt-editor-text-muted: #9a9da4;
  --wt-editor-line-number: #c2c4c9;
  --wt-editor-line-number-active: #282a30;
  --wt-editor-wrap-guide: #edeef1;
  --wt-editor-wrap-guide-active: #d7d9dd;
  --wt-editor-cursor: #3a4bd6;
  --wt-editor-breadcrumb-text: #9a9da4;
}

