    >
      <div className="flex h-full flex-col pt-10 pr-10 pl-10">
        <div
          className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-t-xl border border-b-0"
          style={{
            backgroundColor: "var(--wt-editor-bg)",
            borderColor: "var(--wt-editor-border)",
          }}
        >
          <div
            className="flex shrink-0 items-center gap-3 border-b px-4 py-3"
            style={{ borderColor: "var(--wt-editor-border)" }}
          >
            <TrafficLights />
            <span
              className="text-xs"
              style={{ color: "var(--wt-editor-text-muted)" }}
            >
              internal-transit
            </span>
          </div>

          <div className="min-h-0 flex-1 overflow-hidden px-5 py-4 font-mono">
            {promptStarted && (
              <p className="text-[13px] leading-6" style={{ color: "var(--wt-editor-text-strong)" }}>
                <span style={{ color: "var(--wt-editor-accent)" }}>&#10095; </span>
                {visiblePrompt}
                <BlinkingCursor show={!promptDone} reduceMotion={shouldReduceMotion} />
              </p>
            )}

            {promptDone &&
              RESPONSE_BLOCKS.map((block, i) => (
                <ResponseBlockView key={i} block={block} wordsRevealed={revealedPerBlock[i]} />
              ))}
          </div>

          <div
            className="flex shrink-0 items-center gap-2 border-t px-4 py-2.5"
            style={{ borderColor: "var(--wt-editor-border)" }}
          >
            <span style={{ color: "var(--wt-editor-accent)" }}>&#10095;</span>
            <span
              className="text-[13px]"
              style={{ color: "var(--wt-editor-text-muted)" }}
            >
              {responseDone ? "Ready for the next request" : ""}
            </span>
          </div>

          <div
            className="flex shrink-0 items-center gap-3 border-t px-4 py-2 text-[11px]"
            style={{
              borderColor: "var(--wt-editor-border)",
              color: "var(--wt-editor-text-muted)",
            }}
          >
            <span>Sonnet 5</span>
            <span>&middot;</span>
            <span>internal-transit</span>
            <span>&middot;</span>
            <span>feat/watchtower-case-study</span>
          </div>
        </div>
      </div>
    </div>
  );
}

