        style={{ color: "var(--wt-editor-text-strong)" }}
      >
        {visibleText}
      </p>
    );
  }

  if (block.type === "bullet") {
    return (
      <p className="my-1 pl-4 text-[13px] leading-6" style={{ color: "var(--wt-editor-text-main)" }}>
        <span style={{ color: "var(--wt-editor-accent)" }}>&bull; </span>
        {visibleText}
      </p>
    );
  }

  return (
    <p className="my-2 text-[13px] leading-6" style={{ color: "var(--wt-editor-text-main)" }}>
      {visibleText}
    </p>
  );
}

