11	      <span className="h-3 w-3 rounded-full" style={{ backgroundColor: "#ff5f57" }} />
12	      <span className="h-3 w-3 rounded-full" style={{ backgroundColor: "#febc2e" }} />
13	      <span className="h-3 w-3 rounded-full" style={{ backgroundColor: "#28c840" }} />
14	    </div>
15	  );
16	}
17	
18	function BlinkingCursor({ show, reduceMotion }: { show: boolean; reduceMotion: boolean }) {
19	  if (!show) return null;
20	  return (
21	    <motion.span
22	      aria-hidden="true"
23	      className="ml-[1px] inline-block h-[15px] w-[7px] translate-y-[2px] align-middle"
24	      style={{ backgroundColor: "var(--wt-editor-cursor)" }}
25	      animate={reduceMotion ? { opacity: 1 } : { opacity: [1, 1, 0, 0] }}
26	      transition={
27	        reduceMotion ? undefined : { duration: 1, repeat: Infinity, times: [0, 0.5, 0.51, 1] }
28	      }
29	    />
30	  );
31	}
32	
33	function ResponseBlockView({
34	  block,
35	  wordsRevealed,
36	}: {
37	  block: ResponseBlock;
38	  wordsRevealed: number;
39	}) {
40	  if (wordsRevealed < 0) return null;
41	
42	  if (block.type === "diff") {
43	    const visibleLines = block.lines.slice(0, wordsRevealed);
44	    return (
45	      <div className="my-3">
46	        <p className="mb-1 font-mono text-[13px]" style={{ color: "var(--wt-editor-text-strong)" }}>
47	          <span style={{ color: "var(--wt-editor-diff-add-text)" }}>&bull; </span>
48	          <span className="font-semibold">Update</span>
49	          <span style={{ color: "var(--wt-editor-text-muted)" }}>({block.filePath})</span>
50	        </p>
51	        <p
52	          className="mb-2 pl-4 font-mono text-[12px]"
53	          style={{ color: "var(--wt-editor-text-muted)" }}
54	        >
55	          &#8318; Added {block.addedCount} line{block.addedCount === 1 ? "" : "s"}, removed{" "}
56	          {block.removedCount} line{block.removedCount === 1 ? "" : "s"}
57	        </p>
58	        <div className="overflow-hidden font-mono text-[12px] leading-6">
59	          {visibleLines.map((line, i) => {
60	            const isAdd = line.kind === "add";
61	            const isRemove = line.kind === "remove";
62	            return (
63	              <div
64	                key={i}
65	                className="flex"
66	                style={{
67	                  backgroundColor: isAdd
68	                    ? "var(--wt-editor-diff-add-bg)"
69	                    : isRemove
70	                      ? "var(--wt-editor-diff-remove-bg)"
