80	                <span
81	                  className="w-5 shrink-0 text-center select-none"
82	                  style={{
83	                    color: isAdd
84	                      ? "var(--wt-editor-diff-add-text)"
85	                      : isRemove
86	                        ? "var(--wt-editor-diff-remove-text)"
87	                        : "var(--wt-editor-text-muted)",
88	                  }}
89	                >
90	                  {isAdd ? "+" : isRemove ? "-" : ""}
91	                </span>
92	                <span
93	                  className="flex-1 pr-3 whitespace-pre"
94	                  style={{
95	                    color: isAdd
96	                      ? "var(--wt-editor-diff-add-text)"
97	                      : isRemove
98	                        ? "var(--wt-editor-diff-remove-text)"
99	                        : "var(--wt-editor-text-muted)",
100	                  }}
101	                >
102	                  {line.text}
103	                </span>
104	              </div>
