107	        </div>
108	      </div>
109	    );
110	  }
111	
112	  const words = block.text.split(/\s+/).filter(Boolean);
113	  const visibleText = words.slice(0, wordsRevealed).join(" ");
114	
115	  if (block.type === "heading") {
116	    return (
