133	        {visibleText}
134	      </p>
135	    );
136	  }
137	
138	  return (
139	    <p className="my-2 font-mono text-[13px] leading-6" style={{ color: "var(--wt-editor-text-main)" }}>
140	      {visibleText}
141	    </p>
142	  );
143	}
144	
145	export default function TerminalConversation() {
146	  const rootRef = useRef<HTMLDivElement>(null);
147	  const scrollbackRef = useRef<HTMLDivElement>(null);
148	  const shouldReduceMotion = Boolean(useReducedMotion());
149	
150	  const {
151	    revealedCount: promptRevealedCount,
152	    hasStartedTyping: promptStarted,
153	    isDone: promptDone,
154	  } = useTypewriter(rootRef, PROMPT_TEXT);
155	
156	  const { revealedPerBlock, isDone: responseDone } = useStreamingReveal(
157	    RESPONSE_BLOCKS,
158	    promptDone,
159	  );
160	
161	  const visiblePrompt = PROMPT_TEXT.slice(0, promptRevealedCount);
162	
163	  // Real terminal/chat behavior: scrollback is bottom-anchored, growing
164	  // content pushes older lines up and out of view rather than the frame
165	  // resizing to fit. Re-runs on every reveal tick (prompt typing and
166	  // response streaming both drive this via their changing dependencies).
167	  useEffect(() => {
168	    const el = scrollbackRef.current;
169	    if (!el) return;
170	    el.scrollTop = el.scrollHeight;
171	  }, [promptRevealedCount, revealedPerBlock]);
172	
173	  return (
174	    <div
175	      ref={rootRef}
176	      className="wt-editor relative mt-10 h-145 w-full overflow-hidden rounded-lg border"
177	      style={{ borderColor: "var(--wt-editor-border)" }}
178	    >
179	      <div className="flex h-full flex-col pt-10 pr-10 pl-10">
180	        <div
181	          className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-t-xl border border-b-0"
182	          style={{
183	            backgroundColor: "var(--wt-editor-bg)",
184	            borderColor: "var(--wt-editor-border)",
185	          }}
186	        >
187	          <div
188	            className="flex shrink-0 items-center gap-3 border-b px-4 py-3"
189	            style={{ borderColor: "var(--wt-editor-border)" }}
190	          >
191	            <TrafficLights />
192	            <span className="text-xs" style={{ color: "var(--wt-editor-text-muted)" }}>
193	              project-watchtower
194	            </span>
195	          </div>
196	
197	          {/* Scrollback — only the SUBMITTED prompt + streamed response
198	             live here; the in-progress typed prompt renders in the input
199	             row below until it's "submitted" (promptDone). Bottom-anchored
200	             via the scroll effect above, so new content pushes old content
201	             up and out rather than growing the frame. */}
202	          <div
203	            ref={scrollbackRef}
204	            className="flex min-h-0 flex-1 flex-col justify-end overflow-hidden px-5 py-4 font-mono"
205	          >
206	            {promptDone && (
207	              <p
208	                className="-mx-5 mb-3 px-5 py-2 font-mono text-[13px] leading-6"
209	                style={{
210	                  backgroundColor: "var(--wt-editor-prompt-bg)",
211	                  color: "var(--wt-editor-text-strong)",
212	                }}
213	              >
214	                <span style={{ color: "var(--wt-editor-accent)" }}>&#10095; </span>
215	                {PROMPT_TEXT}
216	              </p>
217	            )}
218	
219	            {promptDone &&
220	              RESPONSE_BLOCKS.map((block, i) => (
221	                <ResponseBlockView key={i} block={block} wordsRevealed={revealedPerBlock[i]} />
222	              ))}
223	          </div>
224	
225	          {/* Input row — shows the prompt typing in place, character by
226	             character, until it's done; then clears back to an idle
227	             prompt marker (the "submitted" prompt has already moved to
228	             the scrollback above by that point). */}
229	          <div
230	            className="flex shrink-0 items-center gap-2 border-t px-4 py-2.5 font-mono text-[13px]"
231	            style={{ borderColor: "oklch(57.8% 0.103 227deg)" }}
232	          >
233	            <span style={{ color: "oklch(78.2% 0.00782 261deg)" }}>&#10095;</span>
234	            {!promptDone && promptStarted && (
235	              <span style={{ color: "var(--wt-editor-text-strong)" }}>
236	                {visiblePrompt}
237	                <BlinkingCursor show reduceMotion={shouldReduceMotion} />
238	              </span>
239	            )}
240	            {promptDone && (
241	              <span style={{ color: "var(--wt-editor-text-muted)" }}>
242	                {responseDone ? "Full send it" : ""}
243	              </span>
244	            )}
245	          </div>
246	
247	          <div
248	            className="flex shrink-0 items-center gap-2 border-t px-4 py-2 text-[11px]"
249	            style={{
250	              borderColor: "oklch(57.8% 0.103 227deg)",
251	              color: "var(--wt-editor-text-muted)",
252	            }}
253	          >
254	            <span>
255	              [<span style={{ color: "var(--wt-editor-model-text)" }}>Sonnet 5</span>]
256	            </span>
257	            <span>|</span>
258	            <span style={{ color: "oklch(53.4% 0.063 186deg)" }}>⏸ plan mode on</span>
259	            <span>|</span>
260	            <span>📁 wallaby</span>
261	            <span>|</span>
262	            <span>🌿 feat/watchtower</span>
263	          </div>
264	        </div>
265	      </div>
266	    </div>
267	  );
